/** Optional movable, translucent copy of the current Tier 1 DPS estimate. */
class DpsEstimateOverlay extends Overlay
{
	private static final int PADDING_X = 10;
	private static final int PADDING_Y = 7;
	private static final int LINE_HEIGHT = 15;
	private static final int MIN_WIDTH = 155;
	private static final int MAX_METHOD_LENGTH = 34;
	private static final Color GOLD = new Color(255, 184, 66);
	private static final Color TEAL = new Color(80, 210, 205);
	private static final Color TEXT = new Color(238, 232, 213);

	private final SlayerGearAdvisorPlugin plugin;
	private final SlayerGearAdvisorConfig config;

	@Inject
	DpsEstimateOverlay(SlayerGearAdvisorPlugin plugin, SlayerGearAdvisorConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.dpsOverlayEnabled()) return null;
		GearRecommendations recommendations = plugin.currentRecommendations();
		if (recommendations == null
			|| recommendations.getState() != GearRecommendations.State.READY
			|| recommendations.getLoadoutTiers().isEmpty()) return null;
		LoadoutOffenseEstimate estimate = recommendations.getLoadoutTiers()
			.get(0).getOffenseEstimate();
		if (!estimate.isAvailable()) return null;

		String method = estimate.getMethodName();
		if (method.isEmpty() && recommendations.getStrategy() != null)
			method = recommendations.getStrategy().getName();
		List<String> lines = displayLines(method, estimate, config.dpsOverlayDetailed());
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
			RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics metrics = graphics.getFontMetrics();
		int width = MIN_WIDTH;
		for (String line : lines)
			width = Math.max(width, metrics.stringWidth(line) + PADDING_X * 2);
		int height = PADDING_Y * 2 + lines.size() * LINE_HEIGHT;
		int opacity = Math.max(0, Math.min(255, config.dpsOverlayOpacity()));
		graphics.setColor(new Color(18, 20, 24, opacity));
		graphics.fillRoundRect(0, 0, width, height, 8, 8);
		graphics.setColor(new Color(GOLD.getRed(), GOLD.getGreen(), GOLD.getBlue(),
			Math.max(90, opacity)));
		graphics.drawRoundRect(0, 0, width - 1, height - 1, 8, 8);

		int baseline = PADDING_Y + metrics.getAscent();
		for (int index = 0; index < lines.size(); index++)
		{
			graphics.setColor(index == 0 ? GOLD : index == 2 ? TEAL : TEXT);
			graphics.drawString(lines.get(index), PADDING_X, baseline + index * LINE_HEIGHT);
		}
		return new Dimension(width, height);
	}

	static List<String> displayLines(
		String methodName, LoadoutOffenseEstimate estimate, boolean detailed)
	{
		List<String> lines = new ArrayList<>();
		lines.add("SBIB DPS ESTIMATE");
		String method = methodName == null ? "" : methodName.trim();
		if (!method.isEmpty()) lines.add(shorten(method, MAX_METHOD_LENGTH));
		lines.add(SlayerGearPanel.formatDps(estimate));
		if (detailed && estimate != null && estimate.hasKillRate())
			lines.add(overlayKillRate(estimate));
		if (detailed && estimate != null && !estimate.getTargetName().isEmpty())
			lines.add("Target: " + shorten(estimate.getTargetName(), MAX_METHOD_LENGTH));
		return lines;
	}

	private static String overlayKillRate(LoadoutOffenseEstimate estimate)
	{
		String ttk = estimate.getMaximumSecondsPerKill()
			> estimate.getMinimumSecondsPerKill() + 0.05
			? String.format(java.util.Locale.ENGLISH, "%.1f–%.1fs TTK",
				estimate.getMinimumSecondsPerKill(), estimate.getMaximumSecondsPerKill())
			: String.format(java.util.Locale.ENGLISH, "%.1fs TTK",
				estimate.getMinimumSecondsPerKill());
		String kills = estimate.getMaximumKillsPerHour()
			> estimate.getMinimumKillsPerHour() + 0.05
			? String.format(java.util.Locale.ENGLISH, "%.0f–%.0f kills/hr",
				estimate.getMinimumKillsPerHour(), estimate.getMaximumKillsPerHour())
			: String.format(java.util.Locale.ENGLISH, "%.0f kills/hr",
				estimate.getMinimumKillsPerHour());
		return ttk + " · " + kills;
	}

	private static String shorten(String value, int length)
	{
		return value.length() <= length ? value : value.substring(0, length - 1) + "…";
	}
}

package com.freearcanes.slayergear;

import net.runelite.api.EquipmentInventorySlot;

/** Models the hidden flat max-hit effect of the elemental amulets. */
final class ElementalAmuletEffect
{
	static final int MAX_HIT_BONUS = 2;
	private static final double HIGHEST_STANDARD_SPELL_BASE_MAX_HIT = 24.0;

	private ElementalAmuletEffect() {}

	static boolean applies(GearStrategy strategy, String itemName)
	{
		if (strategy == null
			|| strategy.getCombatStyle() != CombatStyle.MAGIC
			|| strategy.getElementalWeakness() == ElementalWeakness.NONE)
		{
			return false;
		}

		String name = NameMatcher.normalize(itemName);
		if (name.contains("elemental amulet")) return true;

		switch (strategy.getElementalWeakness())
		{
			case AIR: return name.contains("amulet of air");
			case WATER: return name.contains("amulet of water");
			case EARTH: return name.contains("amulet of earth");
			case FIRE: return name.contains("amulet of fire");
			default: return false;
		}
	}

	static double scoringBonus(
		GearStrategy strategy,
		String itemName,
		EquipmentInventorySlot slot)
	{
		if (slot != EquipmentInventorySlot.AMULET || !applies(strategy, itemName)) return 0;

		// scoreStats values each visible Magic-damage percentage point at 25.
		// A flat +2 is at least an 8.33% increase across standard spells, using
		// the highest base max hit (24) as the conservative comparison point.
		return MAX_HIT_BONUS * 100.0 / HIGHEST_STANDARD_SPELL_BASE_MAX_HIT * 25.0;
	}
}

package com.freearcanes.slayergear;

enum ElementalWeakness
{
	NONE,
	AIR,
	WATER,
	EARTH,
	FIRE;

	String displayName()
	{
		if (this == NONE) return "";
		String lower = name().toLowerCase(java.util.Locale.ENGLISH);
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}
}

package com.freearcanes.slayergear;

/** Expected sustained damage from unambiguous PvM enchanted-bolt procs. */
final class EnchantedBoltEffects
{
	private EnchantedBoltEffects() {}

	static String effectName(String ammoName)
	{
		String ammo = NameMatcher.normalize(ammoName);
		if (!ammo.contains("(e)")) return "";
		if (ammo.contains("ruby")) return "Blood Forfeit EV";
		if (ammo.contains("diamond")) return "Armour Piercing EV";
		if (ammo.contains("opal")) return "Lucky Lightning EV";
		if (ammo.contains("dragonstone")) return "Dragon's Breath EV";
		if (ammo.contains("onyx")) return "Life Leech EV";
		if (ammo.contains("pearl")) return "Sea Curse";
		if (ammo.contains("emerald")) return "Poison utility";
		if (ammo.contains("jade")) return "Knockdown utility";
		if (ammo.contains("sapphire")) return "Prayer utility";
		if (ammo.contains("topaz")) return "PvP-only effect";
		return "";
	}

	static Result apply(String ammoName, String weaponName, double normalDamage,
		double accuracy, int maxHit, TargetDefence target, CombatLevelContext levels)
	{
		String ammo = NameMatcher.normalize(ammoName);
		if (!ammo.contains("(e)")) return Result.none(normalDamage);
		String weapon = NameMatcher.normalize(weaponName);
		boolean zaryte = weapon.contains("zaryte crossbow");
		double diary = levels.hasKandarinHardDiary() ? 1.10 : 1.0;
		double successfulAverage = maxHit / 2.0 + (maxHit > 0 ? 1.0 / (maxHit + 1.0) : 0);

		if (ammo.contains("ruby"))
		{
			double chance = 0.06 * diary;
			if (target.getHitpoints() <= 0) return Result.named(normalDamage, "Ruby proc unavailable (HP unknown)");
			double proc = sustainedRubyProc(target.getHitpoints(), zaryte);
			return Result.named((1 - chance) * normalDamage + chance * proc,
				"Ruby Blood Forfeit sustained EV");
		}
		if (ammo.contains("diamond"))
		{
			double chance = 0.10 * diary;
			int procMax = (int) Math.floor(maxHit * (zaryte ? 1.26 : 1.15));
			double procAverage = procMax / 2.0 + (procMax > 0 ? 1.0 / (procMax + 1.0) : 0);
			return Result.named((1 - chance) * normalDamage + chance * procAverage,
				"Diamond Armour Piercing EV");
		}
		if (ammo.contains("opal"))
		{
			double chance = 0.05 * diary;
			double extra = Math.floor(levels.getBoostedRanged() * 0.10) * (zaryte ? 1.10 : 1.0);
			return Result.named((1 - chance) * normalDamage
				+ chance * (successfulAverage + extra), "Opal Lucky Lightning EV");
		}
		if (ammo.contains("dragonstone") && !target.hasAttribute("dragon")
			&& !target.hasAttribute("fiery"))
		{
			double chance = 0.06 * diary;
			double extra = Math.floor(levels.getBoostedRanged() * 0.20) * (zaryte ? 1.10 : 1.0);
			return Result.named(normalDamage + accuracy * chance * extra, "Dragonstone Dragon's Breath EV");
		}
		if (ammo.contains("onyx") && !target.hasAttribute("undead"))
		{
			double chance = 0.11 * diary;
			double bonus = zaryte ? 0.32 : 0.20;
			return Result.named(normalDamage * (1.0 + chance * bonus), "Onyx Life Leech EV");
		}
		if (ammo.contains("pearl")) return Result.named(normalDamage,
			target.hasAttribute("fiery") ? "Pearl Sea Curse (fiery target)" : "Pearl Sea Curse");
		if (ammo.contains("emerald")) return Result.named(normalDamage, "Emerald poison utility");
		if (ammo.contains("jade")) return Result.named(normalDamage, "Jade knockdown utility");
		if (ammo.contains("sapphire")) return Result.named(normalDamage, "Sapphire prayer utility");
		if (ammo.contains("topaz")) return Result.named(normalDamage, "Topaz PvP-only effect");
		return Result.none(normalDamage);
	}

	/** Average Blood Forfeit damage while the target falls from full HP to zero. */
	static double sustainedRubyProc(int hitpoints, boolean zaryte)
	{
		if (hitpoints <= 0) return 0;
		double percent = zaryte ? 0.22 : 0.20;
		double cap = zaryte ? 110.0 : 100.0;
		double capThreshold = cap / percent;
		if (hitpoints <= capThreshold) return percent * hitpoints / 2.0;
		return (percent * capThreshold * capThreshold / 2.0
			+ cap * (hitpoints - capThreshold)) / hitpoints;
	}

	static final class Result
	{
		private final double damage;
		private final String name;
		private Result(double damage, String name) { this.damage = damage; this.name = name; }
		static Result none(double damage) { return new Result(damage, ""); }
		static Result named(double damage, String name) { return new Result(damage, name); }
		double getDamage() { return damage; }
		String getName() { return name; }
	}
}

package com.freearcanes.slayergear;

/** Conservative item-name policy for charge-dependent and degraded equipment variants. */
final class EquipmentChargePolicy
{
	private EquipmentChargePolicy() {}

	static boolean isUsable(String itemName)
	{
		String name = NameMatcher.normalize(itemName);
		if (name.isEmpty()) return false;
		if (name.contains("(broken)") || name.contains("dormant")
			|| name.contains("depleted") || name.contains("(damaged)"))
		{
			return false;
		}
		if ((name.contains("(uncharged)") || name.startsWith("uncharged ")
			|| name.endsWith("(u)") || name.contains("(inactive)")
			|| name.contains("(empty)")) && chargeStateControlsModeledPerformance(name))
		{
			return false;
		}
		return !isFullyDegradedBarrows(name);
	}

	static String note(String itemName)
	{
		String name = NameMatcher.normalize(itemName);
		if (isCorruptedCrystalWeapon(name)) return "";
		if (has(name, "scythe of vitur", "tumeken's shadow", "sanguinesti staff",
			"trident of the", "uncharged trident", "toxic blowpipe", "toxic staff", "serpentine helm",
			"craw's bow", "webweaver bow", "viggora's chainmace", "ursine chainmace",
			"thammaron's sceptre", "accursed sceptre", "crystal bow",
			"bow of faerdhinen", "blade of saeldor", "crystal helm", "crystal body", "crystal legs",
			"venator bow", "echo venator bow", "tonalztics of ralos",
			"dizana's quiver", "dizana’s quiver")
			|| isBarrowsEquipment(name))
		{
			return "charge-dependent; verify charges before leaving";
		}
		return "";
	}

	private static boolean chargeStateControlsModeledPerformance(String name)
	{
		return has(name, "scythe of vitur", "tumeken's shadow", "sanguinesti staff",
			"trident", "toxic blowpipe", "toxic staff", "serpentine helm",
			"craw's bow", "webweaver bow", "viggora's chainmace", "ursine chainmace",
			"thammaron's sceptre", "accursed sceptre", "crystal bow",
			"bow of faerdhinen", "blade of saeldor", "crystal helm", "crystal body", "crystal legs",
			"venator bow", "echo venator bow", "tonalztics of ralos");
	}

	private static boolean isCorruptedCrystalWeapon(String name)
	{
		return name.contains("(c)")
			&& has(name, "bow of faerdhinen", "blade of saeldor");
	}

	private static boolean isFullyDegradedBarrows(String name)
	{
		return isBarrowsEquipment(name) && name.matches(".*\\s0$");
	}

	private static boolean isBarrowsEquipment(String name)
	{
		return has(name, "ahrim's", "dharok's", "guthan's", "karil's",
			"torag's", "verac's");
	}

	private static boolean has(String name, String... tokens)
	{
		for (String token : tokens) if (name.contains(token)) return true;
		return false;
	}
}

