package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class InventoryCapacityPlan
{
	static final int INVENTORY_CAPACITY = 28;

	private final boolean available;
	private final int occupiedSlots;
	private final int pendingGearSlots;
	private final int requestedSlots;
	private final int plannedSlots;
	private final List<String> reductions;

	private InventoryCapacityPlan(
		boolean available,
		int occupiedSlots,
		int pendingGearSlots,
		int requestedSlots,
		int plannedSlots,
		List<String> reductions)
	{
		this.available = available;
		this.occupiedSlots = Math.max(0, occupiedSlots);
		this.pendingGearSlots = Math.max(0, pendingGearSlots);
		this.requestedSlots = Math.max(0, requestedSlots);
		this.plannedSlots = Math.max(0, plannedSlots);
		this.reductions = Collections.unmodifiableList(new ArrayList<>(reductions));
	}

	static InventoryCapacityPlan unavailable()
	{
		return new InventoryCapacityPlan(false, 0, 0, 0, 0, Collections.emptyList());
	}

	static InventoryCapacityPlan available(
		int occupiedSlots,
		int pendingGearSlots,
		int requestedSlots,
		int plannedSlots,
		List<String> reductions)
	{
		return new InventoryCapacityPlan(
			true, occupiedSlots, pendingGearSlots, requestedSlots, plannedSlots, reductions);
	}

	boolean isAvailable() { return available; }
	int getOccupiedSlots() { return occupiedSlots; }
	int getPendingGearSlots() { return pendingGearSlots; }
	int getRequestedSlots() { return requestedSlots; }
	int getPlannedSlots() { return plannedSlots; }
	int getCapacity() { return INVENTORY_CAPACITY; }
	List<String> getReductions() { return reductions; }
	boolean wasTrimmed() { return requestedSlots > plannedSlots; }
	boolean fits() { return plannedSlots <= INVENTORY_CAPACITY; }
	int getOverBy() { return Math.max(0, plannedSlots - INVENTORY_CAPACITY); }
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Item;

final class InventoryCapacityPlanner
{
	@Inject
	InventoryCapacityPlanner()
	{
	}

	GearRecommendations apply(
		GearRecommendations recommendations,
		Item[] inventoryItems,
		boolean bankPlanLocked,
		boolean bankRefreshPending)
	{
		if (recommendations == null
			|| recommendations.getState() != GearRecommendations.State.READY)
		{
			return recommendations;
		}

		List<SupplyRecommendation> supplies =
			new ArrayList<>(recommendations.getSupplies());
		int occupiedSlots = occupiedSlots(inventoryItems);
		int pendingGearSlots = pendingGearSlots(recommendations);
		int requestedSlots = occupiedSlots + pendingGearSlots + supplySlots(supplies);
		int excess = Math.max(0, requestedSlots - InventoryCapacityPlan.INVENTORY_CAPACITY);
		List<String> reductions = new ArrayList<>();

		List<Integer> trimOrder = new ArrayList<>();
		for (int index = 0; index < supplies.size(); index++)
		{
			SupplyRecommendation supply = supplies.get(index);
			if (!supply.isRequired()
				&& supply.isEnabledForTrip()
				&& supply.isQuantityAdjustable()
				&& additionalSlots(supply) > 0)
			{
				trimOrder.add(index);
			}
		}
		trimOrder.sort(Comparator
			.comparingInt((Integer index) -> trimPriority(supplies.get(index)))
			.thenComparingInt(Integer::intValue));

		for (int index : trimOrder)
		{
			if (excess <= 0)
			{
				break;
			}

			SupplyRecommendation supply = supplies.get(index);
			int currentSlots = additionalSlots(supply);
			int slotsToRemove = Math.min(excess, currentSlots);
			int reducedQuantity = quantityForAdditionalSlots(
				supply, currentSlots - slotsToRemove);
			if (reducedQuantity >= supply.getRecommendedQuantity())
			{
				continue;
			}

			int reduction = supply.getRecommendedQuantity() - reducedQuantity;
			SupplyRecommendation adjusted = supply.withCapacityQuantity(reducedQuantity);
			supplies.set(index, adjusted);
			int freed = currentSlots - additionalSlots(adjusted);
			excess -= freed;
			if (freed > 0)
			{
				reductions.add(supply.getCategory() + " -" + reduction
					+ (supply.getQuantityUnit().isEmpty()
						? "" : " " + supply.getQuantityUnit()));
			}
		}

		int plannedSlots = occupiedSlots + pendingGearSlots + supplySlots(supplies);
		InventoryCapacityPlan plan = InventoryCapacityPlan.available(
			occupiedSlots,
			pendingGearSlots,
			requestedSlots,
			plannedSlots,
			reductions);
		return recommendations.withPreparationState(
			supplies, plan, bankPlanLocked, bankRefreshPending);
	}

	static int occupiedSlots(Item[] items)
	{
		if (items == null)
		{
			return 0;
		}

		int occupied = 0;
		for (Item item : items)
		{
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				occupied++;
			}
		}
		return occupied;
	}

	static int additionalSlots(SupplyRecommendation supply)
	{
		if (supply == null || !supply.isEnabledForTrip())
		{
			return 0;
		}
		if (!supply.hasQuantityTarget())
		{
			return supply.getStatus().isPacked() ? 0 : 1;
		}

		int remaining = supply.getQuantityStillNeeded();
		if (remaining <= 0)
		{
			return 0;
		}
		if (supply.isStackQuantity())
		{
			return supply.getPackedQuantity() > 0 ? 0 : 1;
		}
		if ("doses".equals(supply.getQuantityUnit()))
		{
			int doseSize = Math.max(1, supply.getUnitsPerWithdrawal());
			return (remaining + doseSize - 1) / doseSize;
		}
		return remaining;
	}

	private static int pendingGearSlots(GearRecommendations recommendations)
	{
		if (recommendations.getLoadoutTiers().isEmpty())
		{
			return 0;
		}

		int slots = 0;
		for (GearRecommendation recommendation
			: recommendations.getLoadoutTiers().get(0).getItems().values())
		{
			if (recommendation.isBanked() && !recommendation.isPacked())
			{
				slots++;
			}
		}
		for (GearRecommendation recommendation : recommendations.getWeaponSwitches())
		{
			if (recommendation.isBanked() && !recommendation.isPacked()) slots++;
		}
		return slots;
	}

	private static int supplySlots(List<SupplyRecommendation> supplies)
	{
		int slots = 0;
		for (SupplyRecommendation supply : supplies)
		{
			slots += additionalSlots(supply);
		}
		return slots;
	}

	private static int quantityForAdditionalSlots(
		SupplyRecommendation supply,
		int additionalSlots)
	{
		int safeSlots = Math.max(0, additionalSlots);
		int packed = supply.getPackedQuantity();
		if (supply.isStackQuantity())
		{
			return safeSlots == 0 ? packed : supply.getRecommendedQuantity();
		}
		if ("doses".equals(supply.getQuantityUnit()))
		{
			return Math.min(
				supply.getRecommendedQuantity(),
				packed + safeSlots * Math.max(1, supply.getUnitsPerWithdrawal()));
		}
		return Math.min(supply.getRecommendedQuantity(), packed + safeSlots);
	}

	private static int trimPriority(SupplyRecommendation supply)
	{
		switch (supply.getCategory())
		{
			case "Food":
				return 0;
			case "Run energy":
				return 1;
			case "Goading":
				return 2;
			case "Prayer regen":
				return 3;
			case "Combat boost":
			case "Ranged boost":
			case "Magic boost":
				return 4;
			case "Prayer":
				return 5;
			case "Cannon ammo":
				return 6;
			default:
				return 7;
		}
	}
}

package com.freearcanes.slayergear;

import net.runelite.client.plugins.banktags.BankTagsService;

/**
 * Keeps an Inventory Setups bank tag active while Best-in-Bank owns the item
 * layout. The tag is reopened without its custom layout so Inventory Setups can
 * still observe setup switches and deselection without intercepting withdrawals.
 */
final class InventorySetupBankTagState
{
	private static final String INVENTORY_SETUP_TAG_PREFIX = "_invsetup_";

	private String leasedTag;
	private boolean restoreWithLayout;

	boolean hasActiveInventorySetup(BankTagsService bankTagsService)
	{
		String activeTag = bankTagsService.getActiveTag();
		return activeTag != null && activeTag.startsWith(INVENTORY_SETUP_TAG_PREFIX);
	}

	boolean captureActive(BankTagsService bankTagsService)
	{
		if (!hasActiveInventorySetup(bankTagsService))
		{
			return false;
		}

		String activeTag = bankTagsService.getActiveTag();
		boolean activeHasLayout = bankTagsService.getActiveLayout() != null;
		if (!activeTag.equals(leasedTag) || activeHasLayout)
		{
			// A different setup, or the same setup reopened by Inventory Setups,
			// supersedes the lease currently held by Best-in-Bank.
			leasedTag = activeTag;
			restoreWithLayout = activeHasLayout;
		}
		return true;
	}

	boolean activeNeedsNeutralizing(BankTagsService bankTagsService)
	{
		return captureActive(bankTagsService)
			&& bankTagsService.getActiveLayout() != null;
	}

	void neutralizeActive(BankTagsService bankTagsService)
	{
		if (!captureActive(bankTagsService))
		{
			return;
		}
		openWithoutLayout(bankTagsService);
	}

	void reopenNeutralized(BankTagsService bankTagsService)
	{
		if (leasedTag != null)
		{
			openWithoutLayout(bankTagsService);
		}
	}

	void updateLayoutPreference(boolean useLayouts)
	{
		if (leasedTag != null)
		{
			restoreWithLayout = useLayouts;
		}
	}

	boolean shouldRestore(BankTagsService bankTagsService)
	{
		captureActive(bankTagsService);
		return leasedTag != null
			&& leasedTag.equals(bankTagsService.getActiveTag());
	}

	void restore(BankTagsService bankTagsService, boolean restore)
	{
		if (leasedTag == null || !restore)
		{
			clear();
			return;
		}

		int options = BankTagsService.OPTION_ALLOW_MODIFICATIONS
			| BankTagsService.OPTION_HIDE_TAG_NAME;
		if (!restoreWithLayout)
		{
			options |= BankTagsService.OPTION_NO_LAYOUT;
		}

		String tag = leasedTag;
		clear();
		bankTagsService.openBankTag(tag, options);
	}

	private void openWithoutLayout(BankTagsService bankTagsService)
	{
		bankTagsService.openBankTag(
			leasedTag,
			BankTagsService.OPTION_ALLOW_MODIFICATIONS
				| BankTagsService.OPTION_HIDE_TAG_NAME
				| BankTagsService.OPTION_NO_LAYOUT);
	}

	void clear()
	{
		leasedTag = null;
		restoreWithLayout = false;
	}
}

