package com.freearcanes.slayergear;

import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;

/** Combat modifiers which only exist when multiple compatible items are worn. */
final class LoadoutCombatEffects
{
	private final double effectiveAccuracy;
	private final double effectiveStrength;
	private final double finalAccuracy;
	private final double finalDamage;

	private LoadoutCombatEffects(double effectiveAccuracy, double effectiveStrength,
		double finalAccuracy, double finalDamage)
	{
		this.effectiveAccuracy = effectiveAccuracy;
		this.effectiveStrength = effectiveStrength;
		this.finalAccuracy = finalAccuracy;
		this.finalDamage = finalDamage;
	}

	static LoadoutCombatEffects resolve(
		Map<EquipmentInventorySlot, GearRecommendation> loadout,
		GearStrategy strategy,
		String weaponName)
	{
		double effectiveAccuracy = 1.0;
		double effectiveStrength = 1.0;
		double finalAccuracy = 1.0;
		double finalDamage = 1.0;

		boolean eliteVoid = has(loadout, EquipmentInventorySlot.BODY, "elite void top")
			&& has(loadout, EquipmentInventorySlot.LEGS, "elite void robe");
		boolean voidBase = has(loadout, EquipmentInventorySlot.GLOVES, "void knight gloves")
			&& hasAny(loadout, EquipmentInventorySlot.BODY, "void knight top", "elite void top")
			&& hasAny(loadout, EquipmentInventorySlot.LEGS, "void knight robe", "elite void robe");
		if (voidBase && voidHelmMatches(loadout, strategy.getCombatStyle()))
		{
			switch (strategy.getCombatStyle())
			{
				case MAGIC:
					effectiveAccuracy = 1.45;
					if (eliteVoid) finalDamage = 1.05;
					break;
				case RANGED:
					effectiveAccuracy = 1.10;
					effectiveStrength = eliteVoid ? 1.125 : 1.10;
					break;
				default:
					effectiveAccuracy = 1.10;
					effectiveStrength = 1.10;
					break;
			}
		}

		String weapon = NameMatcher.normalize(weaponName);
		if (strategy.getCombatStyle() == CombatStyle.RANGED
			&& (weapon.contains("crystal bow") || weapon.contains("bow of faerdhinen")))
		{
			double accuracyPercent = 0;
			double damagePercent = 0;
			if (has(loadout, EquipmentInventorySlot.HEAD, "crystal helm"))
			{
				accuracyPercent += 5; damagePercent += 2.5;
			}
			if (has(loadout, EquipmentInventorySlot.BODY, "crystal body"))
			{
				accuracyPercent += 15; damagePercent += 7.5;
			}
			if (has(loadout, EquipmentInventorySlot.LEGS, "crystal legs"))
			{
				accuracyPercent += 10; damagePercent += 5;
			}
			finalAccuracy *= 1.0 + accuracyPercent / 100.0;
			finalDamage *= 1.0 + damagePercent / 100.0;
		}

		if (strategy.getCombatStyle() == CombatStyle.MELEE
			&& strategy.getAttackType() == AttackType.CRUSH)
		{
			int pieces = inquisitorPieces(loadout);
			if (pieces > 0)
			{
				boolean inquisitorMace = weapon.contains("inquisitor's mace");
				double perPiece = inquisitorMace ? 0.025 : 0.005;
				// The mace enhancement replaces the ordinary per-piece/full-set
				// structure: three mace-boosted pieces total 7.5%, not 8.5%.
				double bonus = pieces * perPiece
					+ (pieces == 3 && !inquisitorMace ? 0.01 : 0);
				finalAccuracy *= 1.0 + bonus;
				finalDamage *= 1.0 + bonus;
			}
		}
		return new LoadoutCombatEffects(effectiveAccuracy, effectiveStrength,
			finalAccuracy, finalDamage);
	}

	private static boolean voidHelmMatches(
		Map<EquipmentInventorySlot, GearRecommendation> loadout, CombatStyle style)
	{
		String token = style == CombatStyle.MAGIC ? "void mage helm"
			: style == CombatStyle.RANGED ? "void ranger helm" : "void melee helm";
		return has(loadout, EquipmentInventorySlot.HEAD, token);
	}

	private static int inquisitorPieces(Map<EquipmentInventorySlot, GearRecommendation> loadout)
	{
		int result = 0;
		if (has(loadout, EquipmentInventorySlot.HEAD, "inquisitor's great helm")) result++;
		if (has(loadout, EquipmentInventorySlot.BODY, "inquisitor's hauberk")) result++;
		if (has(loadout, EquipmentInventorySlot.LEGS, "inquisitor's plateskirt")) result++;
		return result;
	}

	private static boolean hasAny(Map<EquipmentInventorySlot, GearRecommendation> loadout,
		EquipmentInventorySlot slot, String... tokens)
	{
		for (String token : tokens) if (has(loadout, slot, token)) return true;
		return false;
	}

	private static boolean has(Map<EquipmentInventorySlot, GearRecommendation> loadout,
		EquipmentInventorySlot slot, String token)
	{
		GearRecommendation item = loadout.get(slot);
		return item != null && NameMatcher.normalize(item.getItemName()).contains(token);
	}

	double getEffectiveAccuracy() { return effectiveAccuracy; }
	double getEffectiveStrength() { return effectiveStrength; }
	double getFinalAccuracy() { return finalAccuracy; }
	double getFinalDamage() { return finalDamage; }
}

package com.freearcanes.slayergear;

/** A comparable, style-aware offensive estimate for one coherent loadout. */
final class LoadoutOffenseEstimate
{
	private static final LoadoutOffenseEstimate UNAVAILABLE =
		new LoadoutOffenseEstimate(0, 0, false);

	private final double damagePerSecond;
	private final double maximumDamagePerSecond;
	private final double relativePercent;
	private final boolean available;
	private final String targetName;
	private final String methodName;
	private final double minimumSecondsPerKill;
	private final double maximumSecondsPerKill;

	private LoadoutOffenseEstimate(double damagePerSecond, double relativePercent, boolean available)
	{
		this(damagePerSecond, damagePerSecond, relativePercent, available, "", "", 0, 0);
	}

	private LoadoutOffenseEstimate(double damagePerSecond, double maximumDamagePerSecond, double relativePercent,
		boolean available, String targetName, String methodName,
		double minimumSecondsPerKill, double maximumSecondsPerKill)
	{
		this.damagePerSecond = Math.max(0, damagePerSecond);
		this.maximumDamagePerSecond = Math.max(this.damagePerSecond, maximumDamagePerSecond);
		this.relativePercent = relativePercent;
		this.available = available;
		this.targetName = targetName == null ? "" : targetName;
		this.methodName = methodName == null ? "" : methodName;
		this.minimumSecondsPerKill = Math.max(0, minimumSecondsPerKill);
		this.maximumSecondsPerKill = Math.max(this.minimumSecondsPerKill, maximumSecondsPerKill);
	}

	static LoadoutOffenseEstimate unavailable()
	{
		return UNAVAILABLE;
	}

	static LoadoutOffenseEstimate estimated(
		double damagePerSecond, double relativePercent, String targetName)
	{
		return new LoadoutOffenseEstimate(damagePerSecond, damagePerSecond,
			relativePercent, true, targetName, "", 0, 0);
	}

	static LoadoutOffenseEstimate range(double minimumDamagePerSecond,
		double maximumDamagePerSecond, double relativePercent, String targetName)
	{
		return range(minimumDamagePerSecond, maximumDamagePerSecond,
			relativePercent, targetName, "");
	}

	static LoadoutOffenseEstimate range(double minimumDamagePerSecond,
		double maximumDamagePerSecond, double relativePercent, String targetName,
		String methodName)
	{
		return new LoadoutOffenseEstimate(minimumDamagePerSecond, maximumDamagePerSecond,
			relativePercent, true, targetName, methodName, 0, 0);
	}

	static LoadoutOffenseEstimate range(double minimumDamagePerSecond,
		double maximumDamagePerSecond, double relativePercent, String targetName,
		String methodName, double minimumSecondsPerKill, double maximumSecondsPerKill)
	{
		return new LoadoutOffenseEstimate(minimumDamagePerSecond, maximumDamagePerSecond,
			relativePercent, true, targetName, methodName,
			minimumSecondsPerKill, maximumSecondsPerKill);
	}

	static LoadoutOffenseEstimate estimated(double damagePerSecond, double relativePercent)
	{
		return estimated(damagePerSecond, relativePercent, "");
	}

	double getDamagePerSecond() { return damagePerSecond; }
	double getMaximumDamagePerSecond() { return maximumDamagePerSecond; }
	boolean isRange() { return maximumDamagePerSecond > damagePerSecond + 0.0005; }
	double getRelativePercent() { return relativePercent; }
	boolean isAvailable() { return available; }
	String getTargetName() { return targetName; }
	String getMethodName() { return methodName; }
	boolean hasKillRate() { return minimumSecondsPerKill > 0; }
	double getMinimumSecondsPerKill() { return minimumSecondsPerKill; }
	double getMaximumSecondsPerKill() { return maximumSecondsPerKill; }
	double getMinimumKillsPerHour() { return maximumSecondsPerKill > 0 ? 3600.0 / maximumSecondsPerKill : 0; }
	double getMaximumKillsPerHour() { return minimumSecondsPerKill > 0 ? 3600.0 / minimumSecondsPerKill : 0; }
}

package com.freearcanes.slayergear;

import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Applies the standard OSRS Wiki attack-roll, hit-chance, max-hit and average
 * damage formulas to loadouts with an unambiguous target.
 */
final class LoadoutOffenseEstimator
{
	private LoadoutOffenseEstimator() {}

	static double estimate(
		Map<EquipmentInventorySlot, GearRecommendation> loadout,
		Map<Integer, GearScorer.BankEquipment> equipmentByCanonicalId,
		GearStrategy strategy,
		TargetDefence target,
		CombatLevelContext levels)
	{
		if (loadout == null || loadout.isEmpty() || strategy == null || target == null
			|| levels == null) return 0;

		GearScorer.BankEquipment weapon = equipmentFor(
			loadout.get(EquipmentInventorySlot.WEAPON), equipmentByCanonicalId);
		String weaponName = weapon == null ? "" : weapon.name;
		GearScorer.BankEquipment ammunition = equipmentFor(
			loadout.get(EquipmentInventorySlot.AMMO), equipmentByCanonicalId);
		String ammunitionName = ammunition == null ? "" : ammunition.name;
		String normalizedWeaponName = NameMatcher.normalize(weaponName);
		boolean eclipseAtlatl = normalizedWeaponName.contains("eclipse atlatl");
		boolean twistedBow = normalizedWeaponName.contains("twisted bow");

		int accuracyBonus = 0;
		int strengthBonus = 0;
		double magicDamagePercent = 0;
		String headgearName = "";
		String amuletName = "";
		int speed = 4;
		for (GearRecommendation recommendation : loadout.values())
		{
			GearScorer.BankEquipment item = equipmentByCanonicalId.get(recommendation.getCanonicalItemId());
			if (item == null || item.stats == null) continue;
			ItemEquipmentStats stats = item.stats;
			if (recommendation.getSlot() == EquipmentInventorySlot.HEAD)
			{
				headgearName = item.name;
			}
			else if (recommendation.getSlot() == EquipmentInventorySlot.AMULET)
			{
				amuletName = item.name;
			}
			switch (strategy.getCombatStyle())
			{
				case MAGIC:
					accuracyBonus += stats.getAmagic();
					magicDamagePercent += GearScorer.effectiveMagicDamageBonus(
						strategy, NameMatcher.normalize(item.name), stats);
					break;
				case RANGED:
					accuracyBonus += stats.getArange();
					// The atlatl uses the entire loadout's Melee Strength bonus,
					// not merely the weapon's own bonus.
					strengthBonus += eclipseAtlatl ? stats.getStr() : stats.getRstr();
					break;
				default:
					accuracyBonus += GearScorer.attackBonus(strategy.getAttackType(), stats);
					strengthBonus += stats.getStr();
					break;
			}
			if (recommendation.getSlot() == EquipmentInventorySlot.WEAPON)
			{
				if (stats.getAspeed() > 0) speed = stats.getAspeed();
				if (strategy.getCombatStyle() == CombatStyle.RANGED)
				{
					strengthBonus += WeaponCombatRules.intrinsicRangedStrength(item.name);
				}
			}
		}
		double taskAccuracyMultiplier = SlayerTaskHeadgear.accuracyMultiplier(
			headgearName, strategy.getCombatStyle());
		double taskDamageMultiplier = SlayerTaskHeadgear.damageMultiplier(
			headgearName, strategy.getCombatStyle());
		LoadoutCombatEffects loadoutEffects = LoadoutCombatEffects.resolve(
			loadout, strategy, weaponName);

		int accuracyLevel;
		double averageHit;
		int maximumHit;
		boolean elementalWeaknessApplies = false;
		switch (strategy.getCombatStyle())
		{
			case MAGIC:
				MagicCombatMethod magicMethod = MagicCombatMethod.resolve(
					strategy, weaponName, levels.getBoostedMagic());
				if (magicMethod == null) return 0;
				elementalWeaknessApplies = magicMethod.isElemental();
				accuracyLevel = levels.getMagicAttack();
				if (normalizedWeaponName.contains("tumeken")
					&& normalizedWeaponName.contains("shadow"))
				{
					int shadowMultiplier = shadowMultiplier(strategy);
					accuracyBonus *= shadowMultiplier;
					magicDamagePercent = Math.min(100,
						magicDamagePercent * shadowMultiplier);
				}
				int elementalAmuletBonus = magicMethod.isElemental()
					&& ElementalAmuletEffect.applies(strategy, amuletName)
					? ElementalAmuletEffect.MAX_HIT_BONUS : 0;
				maximumHit = magicMaxHit(
					magicMethod.getBaseMaxHit() + elementalAmuletBonus, magicDamagePercent,
					levels.getMagicDamagePrayerPercent(), elementalWeaknessApplies
						? strategy.getElementalWeaknessPercent() : 0);
				averageHit = maximumHit / 2.0;
				break;
			case RANGED:
				accuracyLevel = levels.getRangedAttack();
				maximumHit = maxHit((int) Math.floor((eclipseAtlatl
					? levels.getAtlatlStrength() : levels.getRangedStrength())
					* loadoutEffects.getEffectiveStrength()),
					strengthBonus);
				averageHit = maximumHit / 2.0;
				break;
			default:
				accuracyLevel = levels.getAttack();
				maximumHit = maxHit((int) Math.floor(levels.getStrength()
					* loadoutEffects.getEffectiveStrength()), strengthBonus);
				averageHit = maximumHit / 2.0;
				break;
		}
		maximumHit = (int) Math.floor(maximumHit * taskDamageMultiplier);
		maximumHit = (int) Math.floor(maximumHit * loadoutEffects.getFinalDamage());
		if (twistedBow)
		{
			maximumHit = (int) Math.floor(maximumHit
				* TwistedBowEffect.damageMultiplier(target));
		}
		averageHit = maximumHit / 2.0;

		double attackRoll = Math.floor(accuracyLevel
			* loadoutEffects.getEffectiveAccuracy()) * (accuracyBonus + 64.0);
		attackRoll = Math.floor(attackRoll * taskAccuracyMultiplier);
		attackRoll = Math.floor(attackRoll * loadoutEffects.getFinalAccuracy());
		if (twistedBow)
		{
			attackRoll = Math.floor(attackRoll
				* TwistedBowEffect.accuracyMultiplier(target));
		}
		// Target-specific accuracy effects modify the attack roll before the
		// piecewise hit-chance comparison; they do not multiply hit chance.
		attackRoll = Math.floor(attackRoll
			* WeaponCombatRules.accuracyMultiplier(strategy, weaponName));
		if (elementalWeaknessApplies
			&& strategy.getElementalWeaknessPercent() > 0)
		{
			attackRoll = Math.floor(attackRoll
				* (1.0 + strategy.getElementalWeaknessPercent() / 100.0));
		}
		int defenceRoll = target.defenceRoll(strategy, weaponName);
		double accuracy = normalHitChance(attackRoll, defenceRoll);
		double damageMultiplier = WeaponCombatRules.damageMultiplier(strategy, weaponName)
			* WeaponCombatRules.intrinsicDamageMultiplier(strategy, weaponName);
		if (maximumHit > 0)
		{
			// Successful zero-damage rolls are converted to one damage in OSRS.
			averageHit += 1.0 / (maximumHit + 1.0);
		}
		double damagePerAttack = accuracy * averageHit * damageMultiplier;
		if (strategy.getCombatStyle() == CombatStyle.RANGED)
		{
			int effectMaxHit = (int) Math.floor(maximumHit * damageMultiplier);
			damagePerAttack = EnchantedBoltEffects.apply(ammunitionName, weaponName,
				damagePerAttack, accuracy, effectMaxHit, target, levels).getDamage();
			if (eclipseAtlatl && wearsFullEclipse(loadout)
				&& !isImmuneToNormalBurn(target))
			{
				// A successful atlatl hit has a 20% chance to apply a ten-damage
				// burn: two expected burn damage per successful hit. Short kills
				// can lose some delayed damage, so this remains an advisory ceiling.
				damagePerAttack += accuracy * 2.0;
			}
			if (normalizedWeaponName.contains("venator bow"))
			{
				// Initial hit plus two independently accurate bounces whose max hit
				// is individually floored to two-thirds of the original.
				int bounceMax = (int) Math.floor(maximumHit * damageMultiplier * 2.0 / 3.0);
				double bounceAverage = bounceMax / 2.0
					+ (bounceMax > 0 ? 1.0 / (bounceMax + 1.0) : 0);
				damagePerAttack = venatorAggregateDamage(damagePerAttack,
					accuracy, bounceAverage);
			}
		}
		else if (strategy.isAncientAoe())
		{
			// Curated Ancient strategies are explicitly multi-target stack
			// methods. Report their nine-target aggregate throughput.
			damagePerAttack = ancientAggregateDamage(damagePerAttack);
		}
		return damagePerAttack / (Math.max(1, speed) * 0.6);
	}

	private static boolean wearsFullEclipse(
		Map<EquipmentInventorySlot, GearRecommendation> loadout)
	{
		return named(loadout, EquipmentInventorySlot.HEAD, "eclipse moon helm")
			&& named(loadout, EquipmentInventorySlot.BODY, "eclipse moon chestplate")
			&& named(loadout, EquipmentInventorySlot.LEGS, "eclipse moon tassets");
	}

	private static boolean named(Map<EquipmentInventorySlot, GearRecommendation> loadout,
		EquipmentInventorySlot slot, String token)
	{
		GearRecommendation item = loadout.get(slot);
		return item != null && NameMatcher.normalize(item.getItemName()).contains(token);
	}

	static boolean isImmuneToNormalBurn(TargetDefence target)
	{
		String response = NameMatcher.normalize(target.getBurnResponse());
		return response.equals("normal") || response.equals("strong");
	}

	static int shadowMultiplier(GearStrategy strategy)
	{
		String context = NameMatcher.normalize(strategy.getName() + " " + strategy.getLocation());
		return context.contains("tombs of amascut") || context.contains("toa") ? 4 : 3;
	}

	static double venatorAggregateDamage(double initialDamage, double accuracy,
		double bounceAverage)
	{
		return initialDamage + 2.0 * accuracy * bounceAverage;
	}

	static double ancientAggregateDamage(double singleTargetDamage)
	{
		return singleTargetDamage * 9.0;
	}

	static String rangedEffectName(
		Map<EquipmentInventorySlot, GearRecommendation> loadout,
		Map<Integer, GearScorer.BankEquipment> equipmentByCanonicalId)
	{
		GearScorer.BankEquipment ammunition = equipmentFor(
			loadout.get(EquipmentInventorySlot.AMMO), equipmentByCanonicalId);
		if (ammunition == null) return "";
		String effect = EnchantedBoltEffects.effectName(ammunition.name);
		return effect.isEmpty() ? "" : ammunition.name + " · " + effect;
	}

	static int magicMaxHit(int baseMaxHit, double equipmentDamagePercent,
		int prayerDamagePercent, int elementalWeaknessPercent)
	{
		int primary = (int) Math.floor(baseMaxHit
			* (1.0 + Math.max(0, equipmentDamagePercent) / 100.0
				+ Math.max(0, prayerDamagePercent) / 100.0));
		return primary + (int) Math.floor(baseMaxHit
			* Math.max(0, elementalWeaknessPercent) / 100.0);
	}

	private static GearScorer.BankEquipment equipmentFor(
		GearRecommendation recommendation,
		Map<Integer, GearScorer.BankEquipment> equipmentByCanonicalId)
	{
		return recommendation == null ? null
			: equipmentByCanonicalId.get(recommendation.getCanonicalItemId());
	}

	static double normalHitChance(double attackRoll, double defenceRoll)
	{
		if (attackRoll <= 0) return 0;
		if (attackRoll > defenceRoll)
		{
			return 1.0 - (defenceRoll + 2.0) / (2.0 * (attackRoll + 1.0));
		}
		return attackRoll / (2.0 * (defenceRoll + 1.0));
	}

	private static int maxHit(int effectiveLevel, int strengthBonus)
	{
		return Math.max(0, (int) Math.floor(
			0.5 + Math.max(1, effectiveLevel) * (strengthBonus + 64.0) / 640.0));
	}
}

package com.freearcanes.slayergear;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;

final class LoadoutTier
{
	private final int rank;
	private final Map<EquipmentInventorySlot, GearRecommendation> items;
	private final int guidePrice;
	private final int riskCapGp;
	private final LoadoutOffenseEstimate offenseEstimate;

	LoadoutTier(int rank, Map<EquipmentInventorySlot, GearRecommendation> items)
	{
		this(rank, items, 0, 0, LoadoutOffenseEstimate.unavailable());
	}

	LoadoutTier(
		int rank,
		Map<EquipmentInventorySlot, GearRecommendation> items,
		int guidePrice,
		int riskCapGp)
	{
		this(rank, items, guidePrice, riskCapGp, LoadoutOffenseEstimate.unavailable());
	}

	LoadoutTier(
		int rank,
		Map<EquipmentInventorySlot, GearRecommendation> items,
		int guidePrice,
		int riskCapGp,
		LoadoutOffenseEstimate offenseEstimate)
	{
		this.rank = rank;
		EnumMap<EquipmentInventorySlot, GearRecommendation> copy = new EnumMap<>(EquipmentInventorySlot.class);
		copy.putAll(items);
		this.items = Collections.unmodifiableMap(copy);
		this.guidePrice = Math.max(0, guidePrice);
		this.riskCapGp = Math.max(0, riskCapGp);
		this.offenseEstimate = offenseEstimate == null
			? LoadoutOffenseEstimate.unavailable() : offenseEstimate;
