	int getGuidePrice() { return guidePrice; }
	int getRiskCapGp() { return riskCapGp; }
	LoadoutOffenseEstimate getOffenseEstimate() { return offenseEstimate; }
}

package com.freearcanes.slayergear;

/** A Magic attack whose base max hit can be determined without guessing. */
final class MagicCombatMethod
{
	private final String name;
	private final int baseMaxHit;
	private final boolean elemental;

	private MagicCombatMethod(String name, int baseMaxHit, boolean elemental)
	{
		this.name = name;
		this.baseMaxHit = Math.max(0, baseMaxHit);
		this.elemental = elemental;
	}

	static MagicCombatMethod resolve(GearStrategy strategy, String weaponName, int magicLevel)
	{
		String weapon = NameMatcher.normalize(weaponName);
		if (weapon.contains("warped sceptre"))
		{
			return method("Warped sceptre", (8 * magicLevel + 96) / 37);
		}
		if (weapon.contains("trident of the swamp"))
		{
			return method("Trident of the swamp", magicLevel / 3 - 2);
		}
		if (weapon.contains("trident of the seas"))
		{
			return method("Trident of the seas", magicLevel / 3 - 5);
		}
		if (weapon.contains("sanguinesti staff"))
		{
			return method("Sanguinesti staff", magicLevel / 3 + 1);
		}
		if (weapon.contains("tumeken") && weapon.contains("shadow"))
		{
			return method("Tumeken's shadow", magicLevel / 3 + 1);
		}
		if (strategy.isAncientAoe())
		{
			if (magicLevel >= 94) return method("Ice Barrage", 30);
			if (magicLevel >= 70) return method("Ice Burst", 22);
			return null;
		}
		if (strategy.getElementalWeakness() != ElementalWeakness.NONE)
		{
			return elemental(strategy.getElementalWeakness(), magicLevel);
		}
		return null;
	}

	private static MagicCombatMethod elemental(ElementalWeakness element, int level)
	{
		int surge;
		int wave;
		int blast;
		int bolt;
		int strike;
		switch (element)
		{
			case WATER: surge = 85; wave = 65; blast = 47; bolt = 23; strike = 5; break;
			case EARTH: surge = 90; wave = 70; blast = 53; bolt = 29; strike = 9; break;
			case FIRE: surge = 95; wave = 75; blast = 59; bolt = 35; strike = 13; break;
			default: surge = 81; wave = 62; blast = 41; bolt = 17; strike = 1; break;
		}
		if (level >= surge) return elementalMethod(element.displayName() + " Surge", 24);
		if (level >= wave) return elementalMethod(element.displayName() + " Wave", 20);
		if (level >= blast) return elementalMethod(element.displayName() + " Blast", 16);
		if (level >= bolt) return elementalMethod(element.displayName() + " Bolt", 12);
		if (level >= strike) return elementalMethod(element.displayName() + " Strike", 8);
		return null;
	}

	private static MagicCombatMethod method(String name, int baseMaxHit)
	{
		return baseMaxHit <= 0 ? null : new MagicCombatMethod(name, baseMaxHit, false);
	}

	private static MagicCombatMethod elementalMethod(String name, int baseMaxHit)
	{
		return baseMaxHit <= 0 ? null : new MagicCombatMethod(name, baseMaxHit, true);
	}

	String getName() { return name; }
	int getBaseMaxHit() { return baseMaxHit; }
	boolean isElemental() { return elemental; }
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Selects one transparent Objective-aware verdict from already-scored methods. */
final class MethodComparisonAdvisor
{
	private static final double VALUE_DPS_FLOOR = 0.85;

	private MethodComparisonAdvisor() {}

	static List<OwnedMethodComparison> apply(
		List<OwnedMethodComparison> comparisons, GearPriority objective)
	{
		if (comparisons == null || comparisons.isEmpty()) return Collections.emptyList();
		GearPriority selectedObjective = objective == null ? GearPriority.BALANCED : objective;
		double fastestDps = comparisons.stream()
			.mapToDouble(OwnedMethodComparison::averageDps).max().orElse(0);
		int winner = selectedObjective == GearPriority.VALUE
			? valueWinner(comparisons, fastestDps)
			: sustainWinner(comparisons, selectedObjective);
		if (selectedObjective == GearPriority.BALANCED || winner < 0)
		{
			winner = fastestWinner(comparisons);
		}
		String reason = reason(selectedObjective, winner >= 0 ? comparisons.get(winner) : null,
			fastestDps);
		List<OwnedMethodComparison> result = new ArrayList<>(comparisons.size());
		for (int index = 0; index < comparisons.size(); index++)
		{
			result.add(comparisons.get(index).withObjectiveVerdict(index == winner,
				index == winner ? reason : ""));
		}
		return Collections.unmodifiableList(result);
	}

	private static int fastestWinner(List<OwnedMethodComparison> comparisons)
	{
		int winner = -1;
		double best = 0;
		for (int index = 0; index < comparisons.size(); index++)
		{
			double dps = comparisons.get(index).averageDps();
			if (dps > best) { best = dps; winner = index; }
		}
		return winner;
	}

	private static int valueWinner(
		List<OwnedMethodComparison> comparisons, double fastestDps)
	{
		int winner = -1;
		long lowestCost = Long.MAX_VALUE;
		for (int index = 0; index < comparisons.size(); index++)
		{
			OwnedMethodComparison candidate = comparisons.get(index);
			if (candidate.getGpPerKill() <= 0 || candidate.averageDps() <= 0
				|| candidate.averageDps() < fastestDps * VALUE_DPS_FLOOR) continue;
			if (candidate.getGpPerKill() < lowestCost)
			{
				lowestCost = candidate.getGpPerKill();
				winner = index;
			}
		}
		return winner;
	}

	private static int sustainWinner(
		List<OwnedMethodComparison> comparisons, GearPriority objective)
	{
		if (objective == GearPriority.BALANCED || objective == GearPriority.VALUE) return -1;
		int winner = -1;
		double bestDps = 0;
		for (int index = 0; index < comparisons.size(); index++)
		{
			OwnedMethodComparison candidate = comparisons.get(index);
			if (candidate.getSuggestedObjective() != objective) continue;
			if (candidate.averageDps() > bestDps)
			{
				bestDps = candidate.averageDps();
				winner = index;
			}
		}
		return winner;
	}

	private static String reason(
		GearPriority objective, OwnedMethodComparison winner, double fastestDps)
	{
		if (winner == null) return "No measured method verdict is available.";
		if (objective == GearPriority.VALUE && winner.getGpPerKill() > 0)
		{
			return "Lowest modeled GP/kill among methods retaining at least 85% of the fastest DPS.";
		}
		if (objective == GearPriority.PRAYER_FIRST
			|| objective == GearPriority.DEFENCE_FIRST)
		{
			if (winner.getSuggestedObjective() == objective)
			{
				return "Task policy matches this Objective; DPS breaks ties between matching methods.";
			}
			return "No method has a specific policy match, so measured DPS is the fallback.";
		}
		return fastestDps > 0
			? "Highest measured DPS from your eligible owned loadouts."
			: "No measured DPS is available for another method.";
	}
}

package com.freearcanes.slayergear;

import java.util.Locale;

final class NameMatcher
{
	private NameMatcher() {}

	static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ENGLISH);
	}

	static boolean matchesAnyToken(String name, String expression)
	{
		if (expression == null || expression.trim().isEmpty())
		{
			return true;
		}
		String normalized = normalize(name);
		for (String token : expression.toLowerCase(Locale.ENGLISH).split("\\|"))
		{
			String trimmed = token.trim();
			if (!trimmed.isEmpty() && normalized.contains(trimmed))
			{
				return true;
			}
		}
		return false;
	}

	static boolean containsAny(String value, String... tokens)
	{
		String normalized = normalize(value);
		for (String token : tokens)
		{
			if (normalized.contains(normalize(token)))
			{
				return true;
			}
		}
		return false;
	}
}

package com.freearcanes.slayergear;

/** Advisory objective guidance. It never changes the configured objective. */
final class ObjectiveAdvisor
{
	private ObjectiveAdvisor() {}

	static Suggestion suggest(SlayerTaskProfile profile, GearStrategy strategy)
	{
		String key = NameMatcher.normalize(profile == null ? "" : profile.getKey());
		String summary = NameMatcher.normalize(profile == null ? "" : profile.getSummary());
		String method = NameMatcher.normalize(strategy == null ? ""
			: strategy.getName() + " " + strategy.getLocation());
		if (summary.contains("turael/aya speed") || method.contains("turael/aya"))
		{
			return new Suggestion(GearPriority.VALUE,
				"Low-level speed assignments usually need fewer optional consumables.");
		}
		if (key.contains("boss") || BossSlayerCatalog.contains(
			profile == null ? "" : profile.getDisplayName()))
		{
			return new Suggestion(GearPriority.BALANCED,
				"Boss methods benefit most from target-aware damage and shorter kill times.");
		}
		if (strategy != null && (strategy.isAncientAoe()
			|| method.contains("venator") || method.contains("cannon")))
		{
			return new Suggestion(GearPriority.BALANCED,
				"This multi-target method is primarily selected for damage and task speed.");
		}
		if (strategy != null && (strategy.getMagicDefenceWeight() > 0
			|| strategy.getMinimumEquippedWeightKg() > 0))
		{
			return new Suggestion(GearPriority.DEFENCE_FIRST,
				"This method already emphasizes defensive stats or an equipment threshold.");
		}
		if (strategy != null && strategy.getPrayerWeight() >= 1.7)
		{
			return new Suggestion(GearPriority.PRAYER_FIRST,
				"This method has an explicit Prayer-sustain emphasis.");
		}
		return new Suggestion(GearPriority.PRAYER_FIRST,
			"Regular assignments often gain more convenience from longer Prayer trips.");
	}

	static String policy(GearPriority objective)
	{
		if (objective == GearPriority.PRAYER_FIRST)
		{
			return "Prayer gear · +50% Prayer/restoration target";
		}
		if (objective == GearPriority.DEFENCE_FIRST)
		{
			return "Tank armour · +50% food target";
		}
		if (objective == GearPriority.VALUE)
		{
			return "DPS-valid gear · -50% optional boost/support target";
		}
		return "Target DPS gear · +50% boost/aggression target";
	}

	static String changeFromMaxDps(GearPriority objective)
	{
		if (objective == GearPriority.PRAYER_FIRST)
		{
			return "Vs Max DPS: non-weapon slots shift toward Prayer bonus; Prayer and regeneration targets rise 50%.";
		}
		if (objective == GearPriority.DEFENCE_FIRST)
		{
			return "Vs Max DPS: non-weapon slots shift toward total defence; the food target rises 50%.";
		}
		if (objective == GearPriority.VALUE)
		{
			return "Vs Max DPS: DPS-valid gear remains; optional boost, Goading, and regeneration targets fall 50%.";
		}
		return "Max DPS baseline: target-aware tier ordering with 50% more boost and aggression support.";
	}

	static final class Suggestion
	{
		private final GearPriority objective;
		private final String reason;

		Suggestion(GearPriority objective, String reason)
		{
			this.objective = objective;
			this.reason = reason;
		}

		GearPriority getObjective() { return objective; }
		String getReason() { return reason; }
	}
}

