	private static boolean isAraxxor(GearRecommendations recommendations)
	{
		return recommendations != null
			&& NameMatcher.normalize(recommendations.getTaskName()).contains("araxxor");
	}

	private JPanel methodComparisonCard(OwnedMethodComparison comparison)
	{
		RoundedPanel card = new RoundedPanel(SURFACE_RAISED, ROW_RADIUS,
			comparison.isSelected() ? GOLD : BORDER);
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBorder(new EmptyBorder(7, 8, 7, 8));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		String methodTooltip = araxxorSwitchTooltip(comparison.getStrategyName());
		if (methodTooltip != null) card.setToolTipText(methodTooltip);
		card.add(wrappedLabel(comparison.getStrategyName(),
			comparison.isSelected() ? GOLD : comparison.isFastest() ? TEAL : SOFT_TEXT,
			WRAP_WIDTH - 16));
		String marker = comparison.isSelected() ? "SELECTED" : "";
		if (comparison.isObjectiveBest()) marker += marker.isEmpty()
			? "BEST FOR OBJECTIVE" : " · BEST FOR OBJECTIVE";
		else if (comparison.isFastest()) marker += marker.isEmpty()
			? "FASTEST OWNED" : " · FASTEST OWNED";
		if (!marker.isEmpty())
		{
			card.add(smallCaps(marker, comparison.isObjectiveBest() ? GOLD : TEAL));
		}
		card.add(wrappedLabel(comparisonMetricsText(comparison), TEAL, WRAP_WIDTH - 16));
		card.add(wrappedLabel("Suggested Objective: " + comparison.getSuggestedObjective(),
			MUTED_TEXT, WRAP_WIDTH - 16));
		if (comparison.isObjectiveBest() && !comparison.getObjectiveReason().isEmpty())
		{
			card.add(wrappedLabel(comparison.getObjectiveReason(), GOLD, WRAP_WIDTH - 16));
		}
		if (!comparison.getLocation().isEmpty())
		{
			card.add(wrappedLabel(comparison.getLocation(), FAINT_TEXT, WRAP_WIDTH - 16));
		}
		RoundedButton select = new RoundedButton();
		select.setText(comparison.isSelected() ? "Selected" : "Use this method");
		select.setEnabled(!comparison.isSelected());
		select.setAlignmentX(Component.LEFT_ALIGNMENT);
		select.setMaximumSize(new Dimension(Integer.MAX_VALUE, 25));
		if (methodTooltip != null) select.setToolTipText(methodTooltip);
		select.addActionListener(event ->
			methodSelectionHandler.accept(comparison.getStrategyName()));
		card.add(Box.createVerticalStrut(4));
		card.add(select);
		return card;
	}

	private static String strategyTooltip(GearStrategy strategy)
	{
		String switchTooltip = araxxorSwitchTooltip(strategy.getName());
		if (switchTooltip != null) return switchTooltip;
		String explanation = strategy.getRationale();
		return explanation == null || explanation.trim().isEmpty()
			? null : "<html><body style='width:240px'>" + escape(explanation) + "</body></html>";
	}

	private static String araxxorSwitchTooltip(String strategyName)
	{
		String normalized = NameMatcher.normalize(strategyName);
		if (normalized.contains("araxxor") && normalized.contains("noxious halberd"))
		{
			return "<html><body style='width:240px'>Noxious halberd is the safe melee switch for hatched araxytes and mirrorbacks. Its extra reach avoids melee distance and it does not consume ammunition.</body></html>";
		}
		if (normalized.contains("araxxor") && normalized.contains("heavy ballista"))
		{
			return "<html><body style='width:240px'>Heavy ballista is a ranged substitute for the halberd switch. It requires dragon javelins; verify your Ranged level, boost, prayer, and gear can reach the one-hit threshold.</body></html>";
		}
		return null;
	}

	static String comparisonMetricsText(OwnedMethodComparison comparison)
	{
		String metrics = comparison.getOffenseEstimate().isAvailable()
			? formatDps(comparison.getOffenseEstimate()) + " · "
				+ killRateText(comparison.getOffenseEstimate())
			: "DPS unavailable";
		if (comparison.getGpPerKill() > 0)
		{
			metrics += " · " + TripCostEstimator.compactGp(comparison.getGpPerKill())
				+ "/kill · " + TripCostEstimator.compactGp(comparison.getTripGp()) + " trip";
		}
		return metrics;
	}

	private void addReadiness(GearRecommendations recommendations)
	{
		ReadinessReport ready = recommendations.getReadiness();
		boolean readyToLeave = ready.isReadyToLeave();
		RoundedPanel panel = card(SURFACE);
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBorder(new EmptyBorder(9, 10, 9, 10));

		JPanel headline = transparentPanel(new BorderLayout(6, 0));
		headline.setAlignmentX(Component.LEFT_ALIGNMENT);
		JLabel status = new JLabel(readyToLeave ? "Ready to leave bank" : "Prep incomplete");
		status.setFont(FontManager.getRunescapeBoldFont());
		status.setForeground(readyToLeave ? SUCCESS : WARNING);
		headline.add(status, BorderLayout.WEST);
		JLabel dot = new JLabel(readyToLeave ? "●" : "●");
		dot.setForeground(readyToLeave ? SUCCESS : WARNING);
		headline.add(dot, BorderLayout.EAST);
		panel.add(headline);
		panel.add(Box.createVerticalStrut(7));

		JPanel metrics = transparentPanel(new GridLayout(1, 2, 6, 0));
		metrics.setAlignmentX(Component.LEFT_ALIGNMENT);
		metrics.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));
		metrics.add(metricTile("GEAR", ready.getGearPacked() + "/" + ready.getGearTotal(),
			ready.getGearPacked() >= ready.getGearTotal() && ready.getGearTotal() > 0 ? SUCCESS : GOLD));
		metrics.add(metricTile("SUPPLIES", ready.getSuppliesPacked() + "/" + ready.getSuppliesTotal(),
			ready.getSuppliesPacked() >= ready.getSuppliesTotal() ? SUCCESS : BLUE));
		panel.add(metrics);
		panel.add(Box.createVerticalStrut(7));

		int readyCount = ready.getGearPacked() + ready.getSuppliesPacked();
		int totalCount = ready.getGearTotal() + ready.getSuppliesTotal();
		InventoryCapacityPlan inventoryPlan = recommendations.getInventoryPlan();
		String inventoryText = inventoryPlan.isAvailable()
			? " | " + inventoryPlan.getPlannedSlots() + "/"
				+ inventoryPlan.getCapacity() + " slots"
			: "";
		JLabel combined = new JLabel(readyCount + "/" + totalCount
			+ " ready" + inventoryText);
		combined.setFont(FontManager.getRunescapeSmallFont());
		combined.setForeground(
			inventoryPlan.isAvailable() && !inventoryPlan.fits() ? DANGER : SOFT_TEXT);
		combined.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(combined);
		panel.add(Box.createVerticalStrut(6));

		JPanel checks = transparentPanel(new GridLayout(0, 2, 5, 4));
		checks.setAlignmentX(Component.LEFT_ALIGNMENT);
		checks.add(checkLabel("Protection", ready.isProtectionReady()));
		checks.add(checkLabel("Ammo", ready.isWeaponAmmoReady()));
		if (!"Not required".equals(ready.getSpellStatus()))
		{
			JLabel spell = new JLabel(shorten(ready.getSpellStatus(), 30));
			spell.setFont(FontManager.getRunescapeSmallFont());
			spell.setForeground(TEAL);
			spell.setToolTipText(ready.getSpellStatus());
			checks.add(spell);
		}
		panel.add(checks);

		if (inventoryPlan.isAvailable()
			&& (inventoryPlan.wasTrimmed() || !inventoryPlan.fits()))
		{
			panel.add(Box.createVerticalStrut(6));
			String capacityMessage;
			Color capacityColor;
			if (!inventoryPlan.fits())
			{
				capacityMessage = "Inventory plan is over by "
					+ inventoryPlan.getOverBy() + " slot"
					+ (inventoryPlan.getOverBy() == 1 ? "" : "s")
					+ ". Required items were kept.";
				capacityColor = DANGER;
			}
			else
			{
				capacityMessage = "Fit to 28 slots by reducing "
					+ String.join(", ", inventoryPlan.getReductions()) + ".";
				capacityColor = WARNING;
			}
			panel.add(wrappedLabel(capacityMessage, capacityColor, WRAP_WIDTH));
		}

		content.add(panel);

		if (!ready.getMissingCritical().isEmpty())
		{
			content.add(Box.createVerticalStrut(6));
			RoundedPanel alert = card(new Color(48, 36, 29));
			alert.setLayout(new BoxLayout(alert, BoxLayout.Y_AXIS));
			alert.setBorder(new EmptyBorder(8, 10, 8, 10));
			JLabel title = smallCaps("DON'T LEAVE YET", WARNING);
			alert.add(title);
			int count = Math.min(3, ready.getMissingCritical().size());
			for (int i = 0; i < count; i++)
			{
				alert.add(Box.createVerticalStrut(2));
				alert.add(wrappedLabel("• " + ready.getMissingCritical().get(i), SOFT_TEXT, WRAP_WIDTH));
			}
			if (ready.getMissingCritical().size() > count)
			{
				alert.add(Box.createVerticalStrut(2));
				JLabel more = new JLabel("+" + (ready.getMissingCritical().size() - count) + " more");
				more.setFont(FontManager.getRunescapeSmallFont());
				more.setForeground(MUTED_TEXT);
				alert.add(more);
			}
			content.add(alert);
		}
		content.add(Box.createVerticalStrut(10));
	}

