	private TaskCombatCatalog() { }

	static SlayerTaskProfile enrich(SlayerTaskProfile profile, String taskName)
	{
		return enrich(profile, taskName, null);
	}

	static SlayerTaskProfile enrich(SlayerTaskProfile profile, String taskName, String assignedLocation)
	{
		Rule rule = contextualRule(taskName, assignedLocation);

		String summary = profile.getSummary();
		if (!rule.note.isEmpty() && !rule.isGeneric()
			&& !NameMatcher.normalize(summary).contains(NameMatcher.normalize(rule.note)))
		{
			summary = summary + " " + rule.note;
		}

		SlayerTaskProfile.Builder builder = SlayerTaskProfile.builder()
			.key(profile.getKey())
			.displayName(profile.getDisplayName())
			.summary(summary)
			.protectionAdvice(profile.getProtectionAdvice());

		boolean hasMelee = false;
		boolean hasRanged = false;
		boolean hasMagic = false;
		boolean alreadyHasElementMethod = false;
		String elementToken = rule.elementalWeakness.displayName().toLowerCase(Locale.ENGLISH);
		for (GearStrategy source : profile.getStrategies())
		{
			GearStrategy enriched = enrich(source, rule);
			builder.strategy(enriched);
			hasMelee |= source.getCombatStyle() == CombatStyle.MELEE;
			hasRanged |= source.getCombatStyle() == CombatStyle.RANGED;
			hasMagic |= source.getCombatStyle() == CombatStyle.MAGIC;
			if (!elementToken.isEmpty() && source.getCombatStyle() == CombatStyle.MAGIC
				&& NameMatcher.normalize(source.getName()).contains(elementToken)) alreadyHasElementMethod = true;
		}

		// Target-family methods only appear when their signature weapon is owned;
		// requiredWeapon is enforced by the existing eligibility engine.
		if (rule.weaponRule == WeaponRule.DEMONBANE)
		{
			if (!hasRanged)
			{
				builder.strategy(signatureMethod("Demonbane Ranged — Scorching bow", CombatStyle.RANGED, rule, "scorching bow"));
				builder.strategy(signatureMethod("Demonbane Ranged — Holy water", CombatStyle.RANGED, rule, "holy water"));
			}
			if (!hasMagic) builder.strategy(signatureMethod("Demonbane Magic + Mark of Darkness", CombatStyle.MAGIC, rule, "purging staff"));
		}
		else if (rule.weaponRule == WeaponRule.DRAGONBANE)
		{
			if (!hasRanged) builder.strategy(signatureMethod("Dragonbane Ranged", CombatStyle.RANGED, rule, "dragon hunter crossbow"));
			if (!hasMagic) builder.strategy(signatureMethod("Dragonbane Magic", CombatStyle.MAGIC, rule, "dragon hunter wand"));
		}
		else if (rule.weaponRule == WeaponRule.RATBANE)
		{
			if (!hasMelee) builder.strategy(signatureMethod("Ratbane melee", CombatStyle.MELEE, rule, "bone mace"));
			if (!hasRanged) builder.strategy(signatureMethod("Ratbane Ranged", CombatStyle.RANGED, rule, "bone shortbow"));
			if (!hasMagic) builder.strategy(signatureMethod("Ratbane Magic", CombatStyle.MAGIC, rule, "bone staff"));
		}

		// Elemental weakness applies only to Standard-spellbook elemental spells.
		// Add it as an alternate method instead of displacing curated Barrage,
		// Venator, cannon, or other task methods that are intentionally first.
		if (rule.elementalWeakness != ElementalWeakness.NONE && rule.elementalWeaknessPercent >= 30
			&& !alreadyHasElementMethod)
		{
			builder.strategy(elementalMethod(rule));
		}
		return builder.build();
	}

	private static Rule contextualRule(String taskName, String assignedLocation)
	{
		Rule base = RULES.get(taskName);
		if (base == null) base = Rule.generic();

		String task = normalize(taskName);
		String location = normalize(assignedLocation);

		// The Ruins of Tapoyauik blue-dragon variant uses Fire rather than the
		// ordinary blue-dragon Water weakness.
		if (task.equals("blue dragons") || task.equals("blue dragon"))
		{
			if (location.contains("tapoyauik"))
			{
				return dragon(ElementalWeakness.FIRE, 50, true);
			}
		}

		// Trollweiss/Ice Path ice-troll assignments are substantially more
		// vulnerable to Fire than ordinary mountain-troll routes.
		if (task.equals("trolls") || task.equals("troll"))
		{
			if (location.contains("trollweiss") || location.contains("ice path"))
			{
				return element(ElementalWeakness.FIRE, 100,
					"Ice-troll route with a 100% Fire elemental weakness.");
			}
		}

		// Twisted banshees in the Catacombs retain the same Air element but use
		// a 25% weakness instead of an ordinary banshee's 30%.
		if ((task.equals("banshees") || task.equals("banshee"))
			&& location.contains("catacombs"))
		{
			return rule(WeaponRule.ANY, AttackType.BALANCED,
				traits(TargetTrait.UNDEAD, TargetTrait.SPECTRAL),
				ElementalWeakness.AIR, 25,
				"Twisted banshee route with a 25% Air elemental weakness.");
		}

		return base;
	}

	static boolean isAudited(String taskName)
	{
		return RULES.contains(taskName);
	}

	static WeaponRule ruleFor(String taskName)
	{
		Rule rule = RULES.get(taskName);
		return rule == null ? WeaponRule.ANY : rule.weaponRule;
	}

	static AttackType meleeAttackTypeFor(String taskName)
	{
		Rule rule = RULES.get(taskName);
		return rule == null ? AttackType.BALANCED : rule.attackType;
	}

	static Set<TargetTrait> traitsFor(String taskName)
	{
		Rule rule = RULES.get(taskName);
		return rule == null ? Collections.emptySet() : rule.targetTraits;
	}

	static ElementalWeakness elementalWeaknessFor(String taskName)
	{
		Rule rule = RULES.get(taskName);
		return rule == null ? ElementalWeakness.NONE : rule.elementalWeakness;
	}

	static int elementalWeaknessPercentFor(String taskName)
	{
		Rule rule = RULES.get(taskName);
		return rule == null ? 0 : rule.elementalWeaknessPercent;
	}

	static String noteFor(String taskName)
	{
		Rule rule = RULES.get(taskName);
		return rule == null ? Rule.GENERIC_NOTE : rule.note;
	}

	static Set<String> auditedTasks()
	{
		return Collections.unmodifiableSet(new LinkedHashSet<>(RULES.snapshot().keySet()));
	}

	private static GearStrategy signatureMethod(String name, CombatStyle style, Rule rule, String weapon)
	{
		GearStrategy.Builder builder = GearStrategy.builder()
			.name(name)
			.location("Task-dependent")
			.rationale(rule.note)
			.combatStyle(style)
			.weaponRule(rule.weaponRule)
			.targetTraits(rule.targetTraits)
			.elementalWeakness(rule.elementalWeakness, rule.elementalWeaknessPercent)
			.requiredWeapon(weapon);
		if (style == CombatStyle.MELEE) builder.attackType(rule.attackType);
		return builder.build();
	}

	private static GearStrategy elementalMethod(Rule rule)
	{
		String element = rule.elementalWeakness.displayName();
		return GearStrategy.builder()
			.name(element + " Magic")
			.location("Task-dependent")
			.rationale("Standard-spellbook " + element + " spells gain " + rule.elementalWeaknessPercent
				+ "% accuracy and damage from this monster's elemental weakness.")
			.combatStyle(CombatStyle.MAGIC)
			.targetTraits(rule.targetTraits)
			.elementalWeakness(rule.elementalWeakness, rule.elementalWeaknessPercent)
			.build();
	}

	private static GearStrategy enrich(GearStrategy source, Rule rule)
	{
		WeaponRule weaponRule = source.getWeaponRule() == WeaponRule.ANY ? rule.weaponRule : source.getWeaponRule();
		AttackType attackType = source.getAttackType();
		if (source.getCombatStyle() == CombatStyle.MELEE && attackType == AttackType.BALANCED
			&& rule.attackType != AttackType.BALANCED)
		{
			attackType = rule.attackType;
		}

		EnumSet<TargetTrait> traits = EnumSet.noneOf(TargetTrait.class);
		traits.addAll(rule.targetTraits);
		traits.addAll(source.getTargetTraits());
		ElementalWeakness element = source.getElementalWeakness() == ElementalWeakness.NONE
			? rule.elementalWeakness : source.getElementalWeakness();
		int elementPercent = source.getElementalWeakness() == ElementalWeakness.NONE
			? rule.elementalWeaknessPercent : source.getElementalWeaknessPercent();

		return source.toBuilder()
			.attackType(attackType)
			.weaponRule(weaponRule)
			.targetTraits(traits)
			.elementalWeakness(element, elementPercent)
			.build();
	}

	private static Rule demon(ElementalWeakness element, int percent)
	{
		return rule(WeaponRule.DEMONBANE, AttackType.BALANCED, traits(TargetTrait.DEMON), element, percent,
			"Demonic target: Demonbane weapon/spell effects are included in scoring."
				+ (element == ElementalWeakness.NONE ? "" : " " + element.displayName() + " Magic receives a " + percent + "% weakness."));
	}

	private static Rule dragon(ElementalWeakness element, int percent, boolean fiery)
	{
		EnumSet<TargetTrait> targetTraits = traits(TargetTrait.DRAGON);
		if (fiery) targetTraits.add(TargetTrait.FIERY);
		return rule(WeaponRule.DRAGONBANE, AttackType.BALANCED, targetTraits, element, percent,
			"Draconic target: Dragonbane effects are included in scoring."
				+ (element == ElementalWeakness.NONE ? "" : " " + element.displayName() + " Magic receives a " + percent + "% weakness."));
	}

	private static Rule element(ElementalWeakness element, int percent, String note)
	{
		return rule(WeaponRule.ANY, AttackType.BALANCED, traits(), element, percent, note);
	}

	private static Rule rule(WeaponRule weaponRule, AttackType attackType, EnumSet<TargetTrait> traits,
		ElementalWeakness element, int percent, String note)
	{
		return new Rule(weaponRule, attackType, traits, element, percent, note);
	}

	private static EnumSet<TargetTrait> traits(TargetTrait... traits)
	{
		EnumSet<TargetTrait> set = EnumSet.noneOf(TargetTrait.class);
		if (traits != null) Collections.addAll(set, traits);
		return set;
	}

	private static void register(Rule rule, String... taskNames)
	{
		RULES.register(rule, AliasCatalog.CollisionPolicy.REPLACE, taskNames);
	}

	private static void alias(String alias, String sourceTask)
	{
		Rule source = RULES.get(sourceTask);
		if (source != null)
		{
			RULES.register(source, AliasCatalog.CollisionPolicy.REPLACE, alias);
		}
	}

	private static String normalize(String value)
	{
		if (value == null) return "";
		String normalized = value.trim().toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9]+", " ").trim();
		return normalized.startsWith("the ") ? normalized.substring(4) : normalized;
	}

	static Map<String, WeaponRule> weaponRulesSnapshot()
	{
		Map<String, WeaponRule> snapshot = new LinkedHashMap<>();
		for (Map.Entry<String, Rule> entry : RULES.snapshot().entrySet())
		{
			snapshot.put(entry.getKey(), entry.getValue().weaponRule);
		}
		return Collections.unmodifiableMap(snapshot);
	}

	private static final class Rule
	{
		private static final String GENERIC_NOTE = "Generic / no task-wide special weapon modifier encoded.";
		private final WeaponRule weaponRule;
		private final AttackType attackType;
		private final Set<TargetTrait> targetTraits;
		private final ElementalWeakness elementalWeakness;
		private final int elementalWeaknessPercent;
		private final String note;

		private Rule(WeaponRule weaponRule, AttackType attackType, Set<TargetTrait> targetTraits,
			ElementalWeakness elementalWeakness, int elementalWeaknessPercent, String note)
		{
			this.weaponRule = weaponRule;
			this.attackType = attackType;
			this.targetTraits = Collections.unmodifiableSet(targetTraits.isEmpty()
				? EnumSet.noneOf(TargetTrait.class) : EnumSet.copyOf(targetTraits));
			this.elementalWeakness = elementalWeakness == null ? ElementalWeakness.NONE : elementalWeakness;
			this.elementalWeaknessPercent = Math.max(0, elementalWeaknessPercent);
			this.note = note == null ? "" : note;
		}

		private static Rule generic()
		{
			return new Rule(WeaponRule.ANY, AttackType.BALANCED, EnumSet.noneOf(TargetTrait.class),
				ElementalWeakness.NONE, 0, GENERIC_NOTE);
		}

		private boolean isGeneric()
		{
			return GENERIC_NOTE.equals(note);
		}
	}
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class TaskCompletionSummary
{
	private final String taskName;
	private final int kills;
	private final long elapsedSeconds;
	private final List<String> consumed;

	TaskCompletionSummary(String taskName, int kills, long elapsedSeconds, List<String> consumed)
	{
		this.taskName = taskName == null ? "" : taskName;
		this.kills = Math.max(0, kills);
		this.elapsedSeconds = Math.max(0, elapsedSeconds);
		this.consumed = consumed == null ? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(consumed));
	}

	String getTaskName() { return taskName; }
	int getKills() { return kills; }
	long getElapsedSeconds() { return elapsedSeconds; }
	List<String> getConsumed() { return consumed; }
	boolean isAvailable() { return !taskName.isEmpty(); }
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

/** Session-only observed consumption tracker; never guesses from bank quantities. */
final class TaskConsumptionTracker
{
	private String taskName = "";
	private int startingAmount;
	private int latestAmount;
	private long startedAtMillis;
	private final Map<String, TrackedSupply> supplies = new LinkedHashMap<>();

	void start(GearRecommendations recommendations, Item[] packedItems,
		ItemManager itemManager, long nowMillis)
	{
		start(recommendations,
			recommendations == null ? "" : recommendations.getTaskName(),
			recommendations == null ? 0 : recommendations.getTaskAmount(),
			packedItems, itemManager, nowMillis);
	}

	void start(GearRecommendations recommendations, String assignmentName,
		int assignmentAmount, Item[] packedItems, ItemManager itemManager, long nowMillis)
	{
		reset();
		begin(recommendations, assignmentName, assignmentAmount,
			packedItems, itemManager, nowMillis);
	}

	void resume(GearRecommendations recommendations, String assignmentName,
		int assignmentAmount, Item[] packedItems, ItemManager itemManager, long nowMillis)
	{
		String nextTask = assignmentName == null ? "" : assignmentName.trim();
		if (!isActive() || !NameMatcher.normalize(taskName).equals(
			NameMatcher.normalize(nextTask)) || assignmentAmount > latestAmount)
		{
			reset();
			begin(recommendations, nextTask, assignmentAmount,
				packedItems, itemManager, nowMillis);
			return;
		}
		if (recommendations == null
			|| recommendations.getState() != GearRecommendations.State.READY) return;
		latestAmount = Math.max(0, assignmentAmount);
		// Banking starts a fresh inventory checkpoint for every previously tracked
		// category, including one omitted from the newly selected trip plan.
		for (TrackedSupply tracked : supplies.values())
		{
			int units = unitsFor(tracked.canonicalItemId, tracked.unit,
				packedItems, itemManager);
			tracked.resume(tracked.canonicalItemId, tracked.unit, units);
		}
		for (SupplyRecommendation supply : recommendations.getSupplies())
		{
			if (!trackable(supply)) continue;
			int units = unitsFor(supply.getCanonicalItemId(), supply.getQuantityUnit(),
				packedItems, itemManager);
			TrackedSupply tracked = supplies.get(supply.getCategory());
			if (tracked == null)
			{
				supplies.put(supply.getCategory(), new TrackedSupply(
					supply.getCategory(), supply.getCanonicalItemId(),
					supply.getQuantityUnit(), units));
			}
			else
			{
				tracked.resume(supply.getCanonicalItemId(), supply.getQuantityUnit(), units);
			}
		}
	}

	private void begin(GearRecommendations recommendations, String assignmentName,
		int assignmentAmount, Item[] packedItems, ItemManager itemManager, long nowMillis)
	{
		if (recommendations == null
			|| recommendations.getState() != GearRecommendations.State.READY) return;
		taskName = assignmentName == null ? "" : assignmentName.trim();
		if (taskName.isEmpty()) return;
		startingAmount = Math.max(0, assignmentAmount);
		latestAmount = startingAmount;
		startedAtMillis = Math.max(0, nowMillis);
		for (SupplyRecommendation supply : recommendations.getSupplies())
		{
			if (!trackable(supply)) continue;
			int units = unitsFor(supply.getCanonicalItemId(), supply.getQuantityUnit(),
				packedItems, itemManager);
			supplies.put(supply.getCategory(), new TrackedSupply(
				supply.getCategory(), supply.getCanonicalItemId(), supply.getQuantityUnit(), units));
		}
	}

	void observe(Item[] packedItems, ItemManager itemManager, int remainingAmount)
	{
		if (!isActive()) return;
		int nextAmount = Math.max(0, remainingAmount);
		boolean confirmedTaskProgress = nextAmount < latestAmount;
		for (TrackedSupply supply : supplies.values())
		{
			supply.observedUnits = unitsFor(supply.canonicalItemId, supply.unit,
				packedItems, itemManager);
			if (confirmedTaskProgress) supply.commitObservedUse();
		}
		latestAmount = nextAmount;
	}

	TaskCompletionSummary finish(int finalAmount, long nowMillis)
	{
		if (!isActive()) return null;
		int nextAmount = Math.max(0, finalAmount);
		if (nextAmount < latestAmount)
		{
			for (TrackedSupply supply : supplies.values()) supply.commitObservedUse();
		}
		latestAmount = nextAmount;
		List<String> consumed = new ArrayList<>();
		for (TrackedSupply supply : supplies.values())
		{
			int used = supply.consumedUnits;
			if (used > 0) consumed.add(supply.category + " " + used + " " + supply.unit);
		}
		TaskCompletionSummary summary = new TaskCompletionSummary(taskName,
			Math.max(0, startingAmount - latestAmount),
			Math.max(0, nowMillis - startedAtMillis) / 1000L, consumed);
		reset();
		return summary;
	}

	void reset()
	{
		taskName = "";
		startingAmount = 0;
		latestAmount = 0;
		startedAtMillis = 0;
		supplies.clear();
	}

	boolean isActive() { return !taskName.isEmpty(); }

	private static boolean trackable(SupplyRecommendation supply)
	{
		return supply != null && supply.isEnabledForTrip()
			&& supply.hasQuantityTarget() && supply.getCanonicalItemId() > 0;
	}

	static int unitsFor(int canonicalItemId, String unit, Item[] items,
		ItemManager itemManager)
	{
		if (items == null || itemManager == null) return 0;
		int total = 0;
		for (Item item : items)
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0
				|| itemManager.canonicalize(item.getId()) != canonicalItemId) continue;
			if ("doses".equals(unit))
			{
				ItemComposition composition = itemManager.getItemComposition(item.getId());
				int doses = composition == null ? 0
					: SmartSupplyAdvisor.doseScore(composition.getName());
				total += item.getQuantity() * Math.max(1, doses);
			}
			else total += item.getQuantity();
		}
		return total;
	}

	private static final class TrackedSupply
	{
		private final String category;
		private int canonicalItemId;
		private String unit;
		private int checkpointUnits;
		private int observedUnits;
		private int consumedUnits;
		private TrackedSupply(String category, int canonicalItemId, String unit, int units)
		{
			this.category = category;
			this.canonicalItemId = canonicalItemId;
			this.unit = unit;
			this.checkpointUnits = units;
			this.observedUnits = units;
		}

		private void resume(int itemId, String quantityUnit, int units)
		{
			canonicalItemId = itemId;
			unit = quantityUnit;
			checkpointUnits = units;
			observedUnits = units;
		}

		private void commitObservedUse()
		{
			consumedUnits += Math.max(0, checkpointUnits - observedUnits);
			checkpointUnits = observedUnits;
		}
	}
}

package com.freearcanes.slayergear;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class TaskPrepReminderOverlay extends Overlay
{
	private static final long DISPLAY_MILLIS = 6_500L;
	private static final long FADE_MILLIS = 1_200L;
	private static final int HEIGHT = 52;
	private static final int MIN_WIDTH = 285;
	private static final int MAX_WIDTH = 440;
	private static final Color GOLD = new Color(224, 174, 73);
	private static final Color TEXT = new Color(238, 232, 213);
	private static final Color BACKGROUND = new Color(24, 20, 14);

	private final SlayerGearAdvisorConfig config;
	private String title;
	private String message;
	private long expiresAt;

	@Inject
	TaskPrepReminderOverlay(SlayerGearAdvisorPlugin plugin, SlayerGearAdvisorConfig config)
	{
		super(plugin);
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
		setMovable(false);
	}

	void show(GearRecommendations recommendations)
	{
		hide();
		if (!config.prepReminderEnabled() || recommendations == null
			|| recommendations.getState() != GearRecommendations.State.READY) return;

		ReadinessReport readiness = recommendations.getReadiness();
		List<String> reminders = new ArrayList<>();
		for (String critical : readiness.getMissingCritical())
		{
			reminders.add(critical);
			if (reminders.size() == 2) break;
		}
		if (reminders.isEmpty())
		{
			for (SupplyRecommendation supply : recommendations.getSupplies())
			{
				if (shouldRemindSupply(supply))
				{
					String quantity = "";
					if (supply.hasQuantityTarget())
					{
						quantity = supply.isStackQuantity()
							? supply.getQuantityStillNeeded() + " "
							: supply.getWithdrawalsStillNeeded() + "× ";
					}
					reminders.add(quantity + supply.getItemName());
					if (reminders.size() == 2) break;
				}
			}
		}
		if (reminders.isEmpty() && readiness.getGearPacked() < readiness.getGearTotal())
			reminders.add("Gear " + readiness.getGearPacked() + "/" + readiness.getGearTotal() + " packed");
		if (reminders.isEmpty()) return;

		title = readiness.isReadyToLeave() ? "Slayer prep suggestion" : "Slayer prep incomplete";
		message = (readiness.isReadyToLeave() ? "Consider: " : "Missing: ") + String.join("  •  ", reminders);
		expiresAt = System.currentTimeMillis() + DISPLAY_MILLIS;
	}

	void hide()
	{
		expiresAt = 0L;
		title = null;
		message = null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		long remaining = expiresAt - System.currentTimeMillis();
		if (remaining <= 0 || title == null || message == null)
		{
			return null;
		}

		float fade = remaining < FADE_MILLIS
			? Math.max(0f, remaining / (float) FADE_MILLIS)
			: 1f;

		graphics.setRenderingHint(
			RenderingHints.KEY_TEXT_ANTIALIASING,
			RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics bodyMetrics = graphics.getFontMetrics();
		graphics.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics titleMetrics = graphics.getFontMetrics();
		int width = Math.max(
			MIN_WIDTH,
			Math.max(titleMetrics.stringWidth(title), bodyMetrics.stringWidth(message)) + 28);
		width = Math.min(MAX_WIDTH, width);

		graphics.setColor(withAlpha(BACKGROUND, (int) (222 * fade)));
		graphics.fillRoundRect(0, 0, width, HEIGHT, 8, 8);
		graphics.setColor(withAlpha(Color.BLACK, (int) (190 * fade)));
		graphics.drawRoundRect(1, 1, width - 3, HEIGHT - 3, 8, 8);
		graphics.setColor(withAlpha(GOLD, (int) (235 * fade)));
		graphics.drawRoundRect(0, 0, width - 1, HEIGHT - 1, 8, 8);
		graphics.fillRect(9, 7, 3, HEIGHT - 14);

		graphics.setFont(FontManager.getRunescapeBoldFont());
		graphics.setColor(withAlpha(Color.BLACK, (int) (230 * fade)));
		graphics.drawString(title, 19, 20);
		graphics.setColor(withAlpha(GOLD, (int) (255 * fade)));
		graphics.drawString(title, 18, 19);

		graphics.setFont(FontManager.getRunescapeSmallFont());
		graphics.setColor(withAlpha(Color.BLACK, (int) (230 * fade)));
		graphics.drawString(message, 19, 40);
		graphics.setColor(withAlpha(TEXT, (int) (255 * fade)));
		graphics.drawString(message, 18, 39);

		return new Dimension(width, HEIGHT);
	}

	static boolean shouldRemindSupply(SupplyRecommendation supply)
	{
		return supply != null
			&& supply.isEnabledForTrip()
			&& supply.getStatus().isBanked()
			&& (!supply.getStatus().isPacked() || !supply.hasRecommendedQuantityPacked())
			&& (supply.isRequired() || isPrepReminderSupply(supply));
	}

	private static boolean isPrepReminderSupply(SupplyRecommendation supply)
	{
		return "Goading".equals(supply.getCategory())
			|| "Prayer regen".equals(supply.getCategory())
			|| "Poison protection".equals(supply.getCategory())
			|| "Light source".equals(supply.getCategory())
			|| "Light backup".equals(supply.getCategory())
			|| "Cave access".equals(supply.getCategory())
			|| "Desert hydration".equals(supply.getCategory());
	}

	private static Color withAlpha(Color color, int alpha)
	{
		return new Color(
			color.getRed(),
			color.getGreen(),
			color.getBlue(),
			Math.max(0, Math.min(255, alpha)));
	}
}

package com.freearcanes.slayergear;

import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

final class TaskPresetCodec
{
	private static final String PREFIX = "SBIB1;";
	private static final int MAX_TOKEN_LENGTH = 8192;

	private TaskPresetCodec() {}

	static String encode(Map<String, String> values)
	{
		StringBuilder token = new StringBuilder(PREFIX);
		if (values != null)
		{
			for (Map.Entry<String, String> entry : values.entrySet())
			{
				if (!validKey(entry.getKey())) continue;
				String value = entry.getValue() == null ? "" : entry.getValue();
				if (value.length() > 1000) value = value.substring(0, 1000);
				token.append(entry.getKey()).append('=')
					.append(Base64.getUrlEncoder().withoutPadding().encodeToString(
						value.getBytes(StandardCharsets.UTF_8))).append(';');
			}
		}
		return token.toString();
	}

	static Map<String, String> decode(String token)
	{
		if (token == null || !token.startsWith(PREFIX)
			|| token.length() > MAX_TOKEN_LENGTH) return Collections.emptyMap();
		Map<String, String> values = new LinkedHashMap<>();
		try
		{
			for (String part : token.substring(PREFIX.length()).split(";"))
			{
				if (part.isEmpty()) continue;
				int separator = part.indexOf('=');
				if (separator <= 0) return Collections.emptyMap();
				String key = part.substring(0, separator);
				if (!validKey(key)) return Collections.emptyMap();
				String value = new String(Base64.getUrlDecoder().decode(
					part.substring(separator + 1)), StandardCharsets.UTF_8);
				if (value.length() > 1000) return Collections.emptyMap();
				values.put(key, value);
			}
		}
		catch (IllegalArgumentException exception)
		{
			return Collections.emptyMap();
		}
		return values;
	}

	private static boolean validKey(String key)
	{
		return key != null && key.matches("[a-zA-Z][a-zA-Z0-9]{0,39}");
	}
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import net.runelite.api.EquipmentInventorySlot;

final class TaskSafetyRules
{
	private TaskSafetyRules() {}

	static List<GearRequirement> gearRequirements(String taskKey, GearStrategy strategy)
	{
		return gearRequirements(taskKey, strategy, false);
	}

	static List<GearRequirement> gearRequirements(String taskKey, GearStrategy strategy, boolean kourendEliteComplete)
	{
		List<GearRequirement> requirements = new ArrayList<>();
		String key = taskKey == null ? "" : taskKey.toLowerCase(Locale.ENGLISH);

		if (contains(key, "aberrant-spectres"))
		{
			requirements.add(head("Slayer helmet or nose peg required", "slayer helmet|slayer helm|nose peg"));
		}
		if (contains(key, "banshee"))
		{
			requirements.add(head("Earmuffs or Slayer helmet required", "earmuffs|slayer helmet|slayer helm"));
		}
		if (contains(key, "sourhog"))
		{
			requirements.add(head("Reinforced goggles or Slayer helmet required", "reinforced goggles|slayer helmet|slayer helm"));
		}
		if (contains(key, "dust-devils", "smoke-devils"))
		{
			requirements.add(head("Facemask or Slayer helmet required", "facemask|slayer helmet|slayer helm"));
		}
		if (contains(key, "wall-beasts"))
		{
			requirements.add(head("Spiny helmet or Slayer helmet required", "spiny helmet|slayer helmet|slayer helm"));
		}
		if (contains(key, "fever-spiders"))
		{
			requirements.add(GearRequirement.anyOf(
				"Slayer gloves required",
				GearRequirement.option(EquipmentInventorySlot.GLOVES, "slayer gloves")));
		}
		if (contains(key, "basilisk", "cockatrice"))
		{
			requirements.add(shield("Mirror shield or V's shield required", "mirror shield|v's shield"));
		}
		if (contains(key, "harpie-bug-swarms"))
		{
			requirements.add(shield("Lit bug lantern required", "lit bug lantern"));
		}
		if (contains(key, "killerwatts"))
		{
			requirements.add(GearRequirement.anyOf("Insulated boots required",
				GearRequirement.option(EquipmentInventorySlot.BOOTS, "insulated boots")));
		}
		if (!kourendEliteComplete && contains(key, "drakes", "wyrms", "hydra"))
		{
			requirements.add(GearRequirement.anyOf("Karuulm heat-protection boots required",
				GearRequirement.option(EquipmentInventorySlot.BOOTS,
					"boots of stone|boots of brimstone|granite boots")));
		}
		if (contains(key, "skeletal-wyverns", "fossil-wyverns"))
		{
			requirements.add(shield(
				"Wyvern breath protection required",
				"elemental shield|mind shield|dragonfire shield|ancient wyvern shield"));
		}
		if (contains(key, "cave-horrors"))
		{
			requirements.add(GearRequirement.anyOf(
				"Witchwood icon required for the recommended melee setup",
				GearRequirement.option(EquipmentInventorySlot.AMULET, "witchwood icon")));
		}

		if (strategy != null && strategy.getRequiredOffhand() != null)
		{
			requirements.add(shield("Required off-hand", strategy.getRequiredOffhand()));
		}
		if (strategy != null && strategy.getRequiredCape() != null)
		{
			requirements.add(GearRequirement.anyOf(
				"Required cape-slot protection",
				GearRequirement.option(EquipmentInventorySlot.CAPE, strategy.getRequiredCape())));
		}
		return dedupe(requirements);
	}

	private static GearRequirement head(String label, String tokens)
	{
		return GearRequirement.anyOf(label, GearRequirement.option(EquipmentInventorySlot.HEAD, tokens));
	}

	private static GearRequirement shield(String label, String tokens)
	{
		return GearRequirement.anyOf(label, GearRequirement.option(EquipmentInventorySlot.SHIELD, tokens));
	}

	private static boolean contains(String key, String... values)
	{
		for (String value : values)
		{
			if (key.contains(value)) return true;
		}
		return false;
	}

	private static List<GearRequirement> dedupe(List<GearRequirement> input)
	{
		List<GearRequirement> output = new ArrayList<>();
		for (GearRequirement requirement : input)
		{
			boolean duplicate = false;
			for (GearRequirement existing : output)
			{
				if (sameRequirement(existing, requirement))
				{
					duplicate = true;
					break;
				}
			}
			if (!duplicate) output.add(requirement);
		}
		return Collections.unmodifiableList(output);
	}

	private static boolean sameRequirement(GearRequirement a, GearRequirement b)
	{
		for (GearRequirement.Option ao : a.getOptions())
		{
			for (GearRequirement.Option bo : b.getOptions())
			{
				if (ao.getSlot() == bo.getSlot() && ao.hasSameTokens(bo)) return true;
			}
		}
		return false;
	}
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

class TieredBankLayout
{
	private static final Logger log = LoggerFactory.getLogger(TieredBankLayout.class);
	private static final int ITEMS_PER_ROW = 8;
	private static final int EQUIP_PATH_ITEMS_PER_ROW = 4;
	private static final int ITEM_WIDTH = 36;
	private static final int ITEM_HEIGHT = 32;
	private static final int ITEM_X_PADDING = 12;
	private static final int ITEM_Y_PADDING = 4;
	private static final int ITEM_START_X = 51;
	private static final int HEADER_HEIGHT = 21;
	private static final int SECTION_PADDING = 8;
	private static final List<EquipmentInventorySlot> SLOT_ORDER = Arrays.asList(
		EquipmentInventorySlot.HEAD,
		EquipmentInventorySlot.CAPE,
		EquipmentInventorySlot.AMULET,
		EquipmentInventorySlot.WEAPON,
		EquipmentInventorySlot.BODY,
		EquipmentInventorySlot.SHIELD,
		EquipmentInventorySlot.LEGS,
		EquipmentInventorySlot.GLOVES,
		EquipmentInventorySlot.BOOTS,
		EquipmentInventorySlot.RING,
		EquipmentInventorySlot.AMMO
	);

	private final Client client;
	private final ItemManager itemManager;
	private final Map<Widget, Integer> tiersByWidget = new IdentityHashMap<>();
	private final Map<Widget, String> headingsByWidget = new IdentityHashMap<>();
	private final Map<Widget, SupplyRecommendation> suppliesByWidget = new IdentityHashMap<>();
	private boolean resetScrollOnNextLayout;

	@Inject
	TieredBankLayout(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	void activate()
	{
		resetScrollOnNextLayout = true;
		clearMappings();
	}

	void clear()
	{
		resetScrollOnNextLayout = false;
		clearMappings();
	}

	void layout(GearRecommendations recommendations)
	{
		clearMappings();
		Widget itemContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (itemContainer == null || itemContainer.getChildren() == null)
		{
			return;
		}

		Map<Integer, Widget> widgetsByExactItemId = new HashMap<>();
		Map<Integer, Widget> widgetsByCanonicalItemId = new HashMap<>();
		for (Widget child : itemContainer.getChildren())
		{
			if (child == null || child.getItemId() < 0)
			{
				continue;
			}

			int itemId = child.getItemId();
			ItemComposition composition = itemManager.getItemComposition(itemId);
			boolean realItem = child.getItemQuantity() > 0
				&& composition != null
				&& composition.getPlaceholderTemplateId() == -1;
			if (realItem)
			{
				widgetsByExactItemId.putIfAbsent(itemId, child);
				widgetsByCanonicalItemId.putIfAbsent(itemManager.canonicalize(itemId), child);
			}
		}

		for (Widget child : itemContainer.getChildren())
		{
			if (child != null)
			{
				child.setHidden(true);
			}
		}

		Map<Integer, List<TierWidget>> byTier = new HashMap<>();
		Set<Widget> representedGear = new HashSet<>();
		for (Map.Entry<EquipmentInventorySlot, List<GearRecommendation>> entry : recommendations.getBySlot().entrySet())
		{
			for (GearRecommendation recommendation : entry.getValue())
			{
				Widget widget = selectExactOrCanonical(
					widgetsByExactItemId,
					widgetsByCanonicalItemId,
					recommendation.getItemId(),
					recommendation.getCanonicalItemId());
				if (widget != null && !representedGear.add(widget))
				{
					widget = null;
				}
				// Keep a path entry even when the item is already packed. That reserved
				// position prevents the remaining bank widgets from compacting under the
				// mouse after each withdrawal.
				byTier.computeIfAbsent(recommendation.getRank(), ignored -> new ArrayList<>())
					.add(new TierWidget(widget, recommendation));
			}
		}

		List<TierWidget> bossSwitches = new ArrayList<>();
		for (GearRecommendation recommendation : recommendations.getWeaponSwitches())
		{
			Widget widget = selectExactOrCanonical(
				widgetsByExactItemId,
				widgetsByCanonicalItemId,
				recommendation.getItemId(),
				recommendation.getCanonicalItemId());
			if (widget != null && !representedGear.add(widget)) widget = null;
			// Reserve packed switches too, matching the stable Tier 1 equipment path.
			bossSwitches.add(new TierWidget(widget, recommendation));
		}

		List<SupplyWidget> supplies = new ArrayList<>();
		Set<Integer> representedSupplies = new HashSet<>();
		int supplyPathSize = 0;
		for (SupplyRecommendation supply : recommendations.getSupplies())
		{
			if (!supply.isEnabledForTrip()) continue;
			int pathIndex = supplyPathSize++;
			// PACKED_BANKED is intentionally still visible. Consumables should not
			// vanish from the Best-in-Bank view after the first potion/food withdrawal.
			if (!supply.getStatus().isBanked()) continue;
			Widget widget = selectExactOrCanonical(
				widgetsByExactItemId,
				widgetsByCanonicalItemId,
				supply.getItemId(),
				supply.getCanonicalItemId());
			if (widget != null
				&& !representedGear.contains(widget)
				&& representedSupplies.add(supply.getCanonicalItemId()))
			{
				supplies.add(new SupplyWidget(widget, supply, pathIndex));
			}
		}

		Comparator<TierWidget> slotOrder = Comparator
			.comparingInt(value -> slotIndex(value.recommendation.getSlot()));
		int cursorY = 0;
		int gearPlaced = 0;

		// Tier 1 equipment uses four columns, matching the inventory width. Odd rows
		// run right-to-left so the player can withdraw and then equip the set with a
		// short continuous zigzag mouse path.
		List<TierWidget> tierOne = byTier.getOrDefault(1, Collections.emptyList());
		tierOne.sort(slotOrder);
		if (!tierOne.isEmpty())
		{
			int itemStartY = cursorY + HEADER_HEIGHT;
			Widget firstWidget = null;
			for (int index = 0; index < tierOne.size(); index++)
			{
				TierWidget tierWidget = tierOne.get(index);
				Widget widget = tierWidget.widget;
				if (widget == null) continue;
				if (firstWidget == null) firstWidget = widget;
				positionPathWidget(widget, index, itemStartY);
				tiersByWidget.put(widget, 1);
				gearPlaced++;
			}
			if (firstWidget != null)
			{
				headingsByWidget.put(firstWidget, "Tier 1 - Equip path (follow the zigzag)");
			}
			int rows = rowsFor(tierOne.size(), EQUIP_PATH_ITEMS_PER_ROW);
			cursorY = itemStartY + rows * (ITEM_HEIGHT + ITEM_Y_PADDING) + SECTION_PADDING;
		}

		if (!bossSwitches.isEmpty())
		{
			int itemStartY = cursorY + HEADER_HEIGHT;
			Widget firstWidget = null;
			for (int index = 0; index < bossSwitches.size(); index++)
			{
				Widget widget = bossSwitches.get(index).widget;
				if (widget == null) continue;
				if (firstWidget == null) firstWidget = widget;
				positionPathWidget(widget, index, itemStartY);
				tiersByWidget.put(widget, 1);
				gearPlaced++;
			}
			if (firstWidget != null)
			{
				headingsByWidget.put(firstWidget, "Boss switches - specs and phase gear");
			}
			int rows = rowsFor(bossSwitches.size(), EQUIP_PATH_ITEMS_PER_ROW);
			cursorY = itemStartY + rows * (ITEM_HEIGHT + ITEM_Y_PADDING) + SECTION_PADDING;
		}

		// Keep all owned trip supplies in their own Tier 1 path. This includes
		// Goading, Prayer regeneration and the combat-style boost, followed by
		// protection, cannon and general sustain supplies.
		if (supplyPathSize > 0)
		{
			int itemStartY = cursorY + HEADER_HEIGHT;
			Widget firstWidget = null;
			for (SupplyWidget supplyWidget : supplies)
			{
				Widget widget = supplyWidget.widget;
				if (firstWidget == null) firstWidget = widget;
				positionPathWidget(widget, supplyWidget.pathIndex, itemStartY);
				tiersByWidget.put(widget, 1);
				suppliesByWidget.put(widget, supplyWidget.recommendation);
			}
			if (firstWidget != null)
			{
				headingsByWidget.put(firstWidget, "Tier 1 - Potions, tools and trip supplies");
			}
			int rows = rowsFor(supplyPathSize, EQUIP_PATH_ITEMS_PER_ROW);
			cursorY = itemStartY + rows * (ITEM_HEIGHT + ITEM_Y_PADDING) + SECTION_PADDING;
		}

		for (int tier = 2; tier <= 3; tier++)
		{
			List<TierWidget> widgets = byTier.getOrDefault(tier, Collections.emptyList());
			if (widgets.isEmpty())
			{
				continue;
			}

			widgets.sort(slotOrder);
			int itemStartY = cursorY + HEADER_HEIGHT;
			Widget firstWidget = null;
			for (int index = 0; index < widgets.size(); index++)
			{
				TierWidget tierWidget = widgets.get(index);
				Widget widget = tierWidget.widget;
				if (widget == null) continue;
				if (firstWidget == null) firstWidget = widget;
				int x = ITEM_START_X
					+ (index % ITEMS_PER_ROW) * (ITEM_WIDTH + ITEM_X_PADDING);
				int y = itemStartY
					+ (index / ITEMS_PER_ROW) * (ITEM_HEIGHT + ITEM_Y_PADDING);
				positionWidget(widget, x, y);
				tiersByWidget.put(widget, tier);
				gearPlaced++;
			}

			if (firstWidget != null)
			{
				headingsByWidget.put(firstWidget, tierHeading(tier));
			}
			int rows = (widgets.size() + ITEMS_PER_ROW - 1) / ITEMS_PER_ROW;
			cursorY = itemStartY
				+ rows * (ITEM_HEIGHT + ITEM_Y_PADDING)
				+ SECTION_PADDING;
		}

		int scrollHeight = Math.max(cursorY, itemContainer.getHeight());
		itemContainer.setScrollHeight(scrollHeight);
		if (resetScrollOnNextLayout)
		{
			itemContainer.setScrollY(0);
			client.setVarcIntValue(VarClientID.BANK_SCROLLPOS, 0);
			resetScrollOnNextLayout = false;
		}
		else if (itemContainer.getScrollY() > scrollHeight - itemContainer.getHeight())
		{
			itemContainer.setScrollY(Math.max(0, scrollHeight - itemContainer.getHeight()));
		}
		itemContainer.revalidateScroll();
		log.debug(
			"Placed {} currently banked ranked gear items and {} owned supplies into Best-in-Bank layout",
			gearPlaced,
			supplies.size());
	}

	int tierFor(Widget widget)
	{
		return tiersByWidget.getOrDefault(widget, 0);
	}

	String headingFor(Widget widget)
	{
		return headingsByWidget.get(widget);
	}

	SupplyRecommendation supplyFor(Widget widget)
	{
		return suppliesByWidget.get(widget);
	}

	private void clearMappings()
	{
		tiersByWidget.clear();
		headingsByWidget.clear();
		suppliesByWidget.clear();
	}

	private static void positionWidget(Widget widget, int x, int y)
	{
		widget.setHidden(false);
		widget.setOriginalWidth(ITEM_WIDTH);
		widget.setOriginalHeight(ITEM_HEIGHT);
		widget.setOriginalX(x);
		widget.setOriginalY(y);
		widget.revalidate();
	}

	private static void positionPathWidget(Widget widget, int index, int itemStartY)
	{
		int row = index / EQUIP_PATH_ITEMS_PER_ROW;
		int column = zigzagColumn(index, EQUIP_PATH_ITEMS_PER_ROW);
		positionWidget(widget,
			ITEM_START_X + column * (ITEM_WIDTH + ITEM_X_PADDING),
			itemStartY + row * (ITEM_HEIGHT + ITEM_Y_PADDING));
	}

	static int zigzagColumn(int index, int columns)
	{
		if (columns <= 0 || index < 0) return 0;
		int row = index / columns;
		int column = index % columns;
		return row % 2 == 0 ? column : columns - 1 - column;
	}

	static <T> T selectExactOrCanonical(
		Map<Integer, T> exactItems,
		Map<Integer, T> canonicalItems,
		int exactItemId,
		int canonicalItemId)
	{
		T exact = exactItems == null ? null : exactItems.get(exactItemId);
		return exact != null || canonicalItems == null
			? exact
			: canonicalItems.get(canonicalItemId);
	}

	static int rowsFor(int itemCount, int columns)
	{
		return (itemCount + columns - 1) / columns;
	}

	private static String tierHeading(int tier)
	{
		String suffix = tier == 1
			? "Best available equipment"
			: tier == 2 ? "Next loadout swaps" : "Further loadout swaps";
		return "Tier " + tier + " - " + suffix;
	}


	private static int slotIndex(EquipmentInventorySlot slot)
	{
		int index = SLOT_ORDER.indexOf(slot);
		return index < 0 ? Integer.MAX_VALUE : index;
	}

	private static final class TierWidget
	{
		private final Widget widget;
		private final GearRecommendation recommendation;

		private TierWidget(Widget widget, GearRecommendation recommendation)
		{
			this.widget = widget;
			this.recommendation = recommendation;
		}
	}

	private static final class SupplyWidget
	{
		private final Widget widget;
		private final SupplyRecommendation recommendation;
		private final int pathIndex;

		private SupplyWidget(Widget widget, SupplyRecommendation recommendation, int pathIndex)
		{
			this.widget = widget;
			this.recommendation = recommendation;
			this.pathIndex = pathIndex;
		}
	}
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Converts RuneLite's assigned Slayer area into optional carried travel items.
 * The assigned area is authoritative; a curated strategy location is used only
 * when RuneLite has no location-locked assignment.
 */
final class TravelItemAdvisor
{
	private TravelItemAdvisor()
	{
	}

	static List<TravelRule> recommend(
		String assignedLocation,
		GearStrategy strategy,
		SlayerGearAdvisorConfig config)
	{
		if (config == null || !config.travelSuggestionsEnabled())
		{
			return Collections.emptyList();
		}

		String destination = assignedLocation == null || assignedLocation.trim().isEmpty()
			? strategy == null ? "" : strategy.getLocation()
			: assignedLocation.trim();
		String location = NameMatcher.normalize(destination);
		List<TravelRule> rules = new ArrayList<>();
		addHomeTeleport(rules, config.homeTeleportPreference());

		java.util.Optional<SlayerAreaCatalog.Area> assignedArea =
			SlayerAreaCatalog.find(destination);
		if (assignedArea.isPresent())
		{
			addAreaTravel(rules, assignedArea.get(), destination, config);
			return rules;
		}

		if (contains(location,
			"slayer tower",
			"fremennik slayer dungeon",
			"rellekka slayer caves",
			"stronghold slayer cave"))
		{
			rules.add(rule(
				"Slayer ring",
				"Fast access to this Slayer destination",
				slayerRingNames(config.slayerRingPreference())));
		}
		else if (contains(location, "catacombs", "chasm of fire", "kourend"))
		{
			rules.add(rule(
				"Kourend teleport",
				"Travel toward " + destination,
				kourendNames(config.kourendTeleportPreference())));
		}
		else if (contains(location, "karuulm"))
		{
			rules.add(rule(
				"Mount Karuulm travel",
				"Travel toward the Karuulm Slayer Dungeon",
				merge(
					new String[]{"rada's blessing"},
					fairyRingNames(config.fairyRingPreference()))));
		}
		else if (contains(location, "fossil island"))
		{
			rules.add(rule(
				"Digsite pendant",
				"Travel to Fossil Island",
				"digsite pendant"));
		}
		else if (contains(location,
			"prifddinas",
			"iorwerth",
			"lletya",
			"mourner tunnel"))
		{
			rules.add(rule(
				"Teleport crystal",
				"Travel toward the assigned elven location",
				"eternal teleport crystal",
				"teleport crystal"));
		}
		else if (contains(location,
			"meiyerditch",
			"morytania spider nest",
			"darkmeyer",
			"vampyrium"))
		{
			rules.add(rule(
				"Drakan's medallion",
				"Travel toward the assigned Morytania location",
				"drakan's medallion"));
		}
		else if (contains(location, "god wars", "trollheim"))
		{
			rules.add(spellRoute(
				"Trollheim teleport",
				"Travel toward God Wars Dungeon",
				"trollheim teleport",
				config.spellTeleportPreference()));
		}
		else if (contains(location, "lunar isle"))
		{
			rules.add(spellRoute(
				"Lunar Isle teleport",
				"Travel to Lunar Isle",
				"lunar isle teleport",
				config.spellTeleportPreference()));
		}
		else if (contains(location,
			"taverley",
			"burthorpe",
			"lighthouse",
			"waterfall dungeon",
			"ancient cavern"))
		{
			rules.add(rule(
				"Games necklace",
				"Travel near " + destination,
				"games necklace"));
		}
		else if (contains(location,
			"brimhaven",
			"karamja",
			"harpie",
			"tai bwo wannai"))
		{
			rules.add(rule(
				"Karamja travel",
				"Travel toward the assigned Karamja location",
				"karamja gloves",
				"tai bwo wannai teleport"));
		}
		else if (contains(location,
			"zanaris",
			"killerwatt",
			"kalphite",
			"kharidian desert",
			"smoke dungeon"))
		{
			rules.add(rule(
				"Fairy ring access",
				"Use a nearby fairy-ring route",
				fairyRingNames(config.fairyRingPreference())));
		}
		else if (contains(location, "dorgesh-kaan"))
		{
			rules.add(rule(
				"Dorgesh-kaan sphere",
				"Travel toward Dorgesh-Kaan",
				"dorgesh-kaan sphere"));
		}

		return rules;
	}

	private static void addAreaTravel(
		List<TravelRule> rules,
		SlayerAreaCatalog.Area area,
		String destination,
		SlayerGearAdvisorConfig config)
	{
		switch (area.getTravelFamily())
		{
			case VARLAMORE:
				rules.add(rule("Varlamore travel", "Travel toward " + destination,
					"pendant of ates", "quetzal whistle"));
				break;
			case KOUREND:
				rules.add(rule("Kourend teleport", "Travel toward " + destination,
					kourendNames(config.kourendTeleportPreference())));
				break;
			case FAIRY_RING:
				rules.add(rule("Fairy ring access", "Use a nearby fairy-ring route",
					fairyRingNames(config.fairyRingPreference())));
				break;
			case DUELING:
				rules.add(rule("Ring of dueling", "Travel toward " + destination,
					"ring of dueling"));
				break;
			case KARUULM:
				rules.add(rule("Mount Karuulm travel", "Travel toward the Karuulm Slayer Dungeon",
					merge(new String[]{"rada's blessing"}, fairyRingNames(config.fairyRingPreference()))));
				break;
			case SLAYER_RING:
				rules.add(rule("Slayer ring", "Fast access to this Slayer destination",
					slayerRingNames(config.slayerRingPreference())));
				break;
			case GAMES_NECKLACE:
				rules.add(rule("Games necklace", "Travel near " + destination, "games necklace"));
				break;
			case KARAMJA:
				rules.add(rule("Karamja travel", "Travel toward " + destination,
					"karamja gloves", "tai bwo wannai teleport"));
				break;
			case ARDOUGNE:
				rules.add(spellRoute("Ardougne teleport", "Travel toward " + destination,
					"ardougne teleport", config.spellTeleportPreference()));
				break;
			case TROLLHEIM:
				rules.add(spellRoute("Trollheim teleport", "Travel toward " + destination,
					"trollheim teleport", config.spellTeleportPreference()));
				break;
			case FREMENNIK:
				rules.add(rule("Fremennik travel", "Travel toward " + destination,
					"enchanted lyre", "waterbirth teleport", "games necklace"));
				break;
			case ELVEN:
				rules.add(rule("Teleport crystal", "Travel toward the assigned elven location",
					"eternal teleport crystal", "teleport crystal"));
				break;
			case DRAKAN:
				rules.add(rule("Drakan's medallion", "Travel toward " + destination,
					"drakan's medallion"));
				break;
			case DIGSITE:
				rules.add(rule("Digsite pendant", "Travel toward " + destination,
					"digsite pendant"));
				break;
			case MYTHS_GUILD:
				rules.add(rule("Mythical cape", "Travel toward the Myths' Guild",
					"mythical cape"));
				break;
			case SKULL_SCEPTRE:
				rules.add(rule("Skull sceptre", "Travel to the Stronghold of Security",
					"skull sceptre"));
				break;
			case WATCHTOWER:
				rules.add(spellRoute("Watchtower teleport", "Travel toward the Ogre Enclave",
					"watchtower teleport", config.spellTeleportPreference()));
				break;
			case DORGESH_KAAN:
				rules.add(rule("Dorgesh-kaan sphere", "Travel toward Dorgesh-Kaan",
					"dorgesh-kaan sphere"));
				break;
			case NONE:
			default:
				// Some destinations, such as Sailing islands, have no useful
				// carryable teleport item. Do not invent a packing requirement.
				break;
		}
	}

	private static void addHomeTeleport(
		List<TravelRule> rules,
		HomeTeleportPreference preference)
	{
		HomeTeleportPreference selected = preference == null
			? HomeTeleportPreference.TELEPORT_TO_HOUSE : preference;
		switch (selected)
		{
			case MAX_CAPE:
				rules.add(rule(
					"Max cape",
					"Preferred home and player-owned-house travel",
					"max cape"));
				break;
			case CONSTRUCTION_CAPE:
				rules.add(rule(
					"Construction cape",
					"Preferred home and player-owned-house travel",
					"construct. cape",
					"construction cape"));
				break;
			case RUNES:
				rules.add(rule(
					"Teleport to House runes",
					"Law rune reminder; ensure an Air and Earth rune source is also available",
					"law rune"));
				break;
			case RUNE_POUCH:
				rules.add(rule(
					"Rune pouch",
					"Preferred compact home teleport; verify Law, Air, and Earth runes are loaded",
					"divine rune pouch",
					"rune pouch"));
				break;
			case NONE:
				break;
			case TELEPORT_TO_HOUSE:
			default:
				rules.add(rule(
					"Teleport to house",
					"Preferred home and player-owned-house travel",
					"teleport to house"));
				break;
		}
	}

	private static TravelRule spellRoute(
		String fallback,
		String reason,
		String tabletName,
		SpellTeleportPreference preference)
	{
		if (preference == SpellTeleportPreference.MAX_CAPE_FIRST)
		{
			return rule(fallback, reason, "max cape", tabletName, "law rune");
		}
		if (preference == SpellTeleportPreference.RUNES_FIRST)
		{
			return rule(fallback, reason, "law rune", tabletName);
		}
		return rule(fallback, reason, tabletName, "law rune");
	}

	private static String[] slayerRingNames(SlayerRingPreference preference)
	{
		return preference == SlayerRingPreference.CHARGED_FIRST
			? new String[]{"slayer ring (", "eternal slayer ring"}
			: new String[]{"eternal slayer ring", "slayer ring ("};
	}

	private static String[] fairyRingNames(FairyRingPreference preference)
	{
		if (preference == FairyRingPreference.MAX_CAPE_FIRST)
		{
			return new String[]{"max cape", "quest point cape", "lunar staff", "dramen staff"};
		}
		if (preference == FairyRingPreference.LUNAR_STAFF_FIRST)
		{
			return new String[]{"lunar staff", "dramen staff", "quest point cape"};
		}
		if (preference == FairyRingPreference.DRAMEN_STAFF_FIRST)
		{
			return new String[]{"dramen staff", "lunar staff", "quest point cape"};
		}
		return new String[]{"quest point cape", "lunar staff", "dramen staff"};
	}

	private static String[] kourendNames(KourendTeleportPreference preference)
	{
		if (preference == KourendTeleportPreference.MAX_CAPE_FIRST)
		{
			return new String[]{"max cape", "xeric's talisman", "rada's blessing", "kourend castle teleport"};
		}
		if (preference == KourendTeleportPreference.RADAS_BLESSING_FIRST)
		{
			return new String[]{"rada's blessing", "xeric's talisman", "kourend castle teleport"};
		}
		if (preference == KourendTeleportPreference.KOUREND_TELEPORT_FIRST)
		{
			return new String[]{"kourend castle teleport", "xeric's talisman", "rada's blessing"};
		}
		return new String[]{"xeric's talisman", "rada's blessing", "kourend castle teleport"};
	}

	private static String[] merge(String[] first, String[] second)
	{
		String[] result = new String[first.length + second.length];
		System.arraycopy(first, 0, result, 0, first.length);
		System.arraycopy(second, 0, result, first.length, second.length);
		return result;
	}

	private static boolean contains(String location, String... fragments)
	{
		for (String fragment : fragments)
		{
			if (location.contains(NameMatcher.normalize(fragment)))
			{
				return true;
			}
		}
		return false;
	}

	private static TravelRule rule(
		String fallback,
		String reason,
		String... preferredNames)
	{
		return new TravelRule(fallback, reason, preferredNames);
	}

	static final class TravelRule
	{
		private final String fallback;
		private final String reason;
		private final String[] preferredNames;

		private TravelRule(
			String fallback,
			String reason,
			String[] preferredNames)
		{
			this.fallback = fallback;
			this.reason = reason;
			this.preferredNames = preferredNames.clone();
		}

		String getFallback() { return fallback; }
		String getReason() { return reason; }
		String[] getPreferredNames() { return preferredNames.clone(); }
	}
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class TripCostEstimate
{
	private final long totalGp;
	private final int plannedKills;
	private final List<String> breakdown;

	TripCostEstimate(long totalGp, int plannedKills, List<String> breakdown)
	{
		this.totalGp = Math.max(0, totalGp);
		this.plannedKills = Math.max(0, plannedKills);
		this.breakdown = breakdown == null ? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(breakdown));
	}

	long getTotalGp() { return totalGp; }
	int getPlannedKills() { return plannedKills; }
	long getGpPerKill() { return plannedKills <= 0 ? 0 : (totalGp + plannedKills - 1) / plannedKills; }
	List<String> getBreakdown() { return breakdown; }
	boolean isAvailable() { return totalGp > 0 && plannedKills > 0; }
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemStats;
import net.runelite.client.game.ItemManager;

/** GE-guide estimate for planned supplies and directly observable combat consumables. */
final class TripCostEstimator
{
	private TripCostEstimator() {}

	static TripCostEstimate estimate(List<SupplyRecommendation> supplies,
		ItemManager itemManager, int plannedKills)
	{
		return finish(supplyCosts(supplies, itemManager), plannedKills);
	}

	static TripCostEstimate estimate(GearRecommendations recommendations,
		ItemManager itemManager, int plannedKills)
	{
		List<CategoryCost> costs = supplyCosts(
			recommendations == null ? null : recommendations.getSupplies(), itemManager);
		addCombatConsumables(costs, recommendations, itemManager, plannedKills);
		return finish(costs, plannedKills);
	}

	private static List<CategoryCost> supplyCosts(List<SupplyRecommendation> supplies,
		ItemManager itemManager)
	{
		List<CategoryCost> costs = new ArrayList<>();
		if (supplies == null || itemManager == null) return costs;
		for (SupplyRecommendation supply : supplies)
		{
			if (!supply.isEnabledForTrip() || !supply.hasQuantityTarget()
				|| supply.getItemId() <= 0) continue;
			int price = Math.max(0, itemManager.getItemPrice(supply.getItemId()));
			if (price == 0) continue;
			long count = supply.getRecommendedQuantity();
			if ("doses".equals(supply.getQuantityUnit()))
			{
				int doses = Math.max(1, SmartSupplyAdvisor.doseScore(supply.getItemName()));
				count = (count + doses - 1) / doses;
			}
			long cost = (long) price * count;
			if (cost > 0) costs.add(new CategoryCost(supply.getCategory(), cost));
		}
		return costs;
	}

	private static TripCostEstimate finish(List<CategoryCost> costs, int plannedKills)
	{
		long total = 0;
		for (CategoryCost cost : costs) total += cost.cost;
		costs.sort(Comparator.comparingLong(CategoryCost::getCost).reversed());
		List<String> breakdown = new ArrayList<>();
		for (int index = 0; index < Math.min(3, costs.size()); index++)
		{
			CategoryCost cost = costs.get(index);
			breakdown.add(cost.category + " " + compactGp(cost.cost));
		}
		return new TripCostEstimate(total, plannedKills, breakdown);
	}

	private static void addCombatConsumables(List<CategoryCost> costs,
		GearRecommendations recommendations, ItemManager itemManager, int plannedKills)
	{
		if (recommendations == null || itemManager == null || plannedKills <= 0
			|| recommendations.getState() != GearRecommendations.State.READY
			|| recommendations.getLoadoutTiers().isEmpty()) return;
		LoadoutTier tier = recommendations.getLoadoutTiers().get(0);
		LoadoutOffenseEstimate offense = tier.getOffenseEstimate();
		GearRecommendation weapon = tier.get(EquipmentInventorySlot.WEAPON);
		if (weapon == null || offense == null || !offense.hasKillRate()) return;
		ItemStats weaponStats = itemManager.getItemStats(weapon.getItemId());
		if (weaponStats == null || weaponStats.getEquipment() == null
			|| weaponStats.getEquipment().getAspeed() <= 0) return;
		double secondsPerKill = (offense.getMinimumSecondsPerKill()
			+ offense.getMaximumSecondsPerKill()) / 2.0;
		long attacks = Math.max(1L, (long) Math.ceil(plannedKills * secondsPerKill
			/ (weaponStats.getEquipment().getAspeed() * 0.6)));
		if (recommendations.getStrategy() != null
			&& recommendations.getStrategy().getCombatStyle() == CombatStyle.RANGED)
		{
			addRangedAmmoCost(costs, tier, itemManager, attacks);
		}
		else if (recommendations.getStrategy() != null
			&& recommendations.getStrategy().getCombatStyle() == CombatStyle.MAGIC)
		{
			addMagicCost(costs, tier, itemManager, attacks, offense.getMethodName());
		}
	}

	private static void addRangedAmmoCost(List<CategoryCost> costs, LoadoutTier tier,
		ItemManager itemManager, long attacks)
	{
		GearRecommendation weapon = tier.get(EquipmentInventorySlot.WEAPON);
		GearRecommendation ammo = tier.get(EquipmentInventorySlot.AMMO);
		if (weapon == null || ammo == null
			|| !RangedAmmoPolicy.usesAmmoSlot(weapon.getItemName())
			|| !RangedAmmoPolicy.isCompatible(weapon.getItemName(), ammo.getItemName())) return;
		double recovery = recoverableAmmo(ammo.getItemName())
			? ammoRecoveryRate(tier.get(EquipmentInventorySlot.CAPE)) : 0;
		long consumed = Math.max(1L, (long) Math.ceil(attacks * (1.0 - recovery)));
		long cost = consumed * Math.max(0, itemManager.getItemPrice(ammo.getItemId()));
		if (cost > 0) costs.add(new CategoryCost("Worn ammunition", cost));
	}

	private static double ammoRecoveryRate(GearRecommendation cape)
	{
		if (cape == null) return 0;
		String name = NameMatcher.normalize(cape.getItemName());
		if (name.contains("assembler")) return 0.80;
		if (name.contains("accumulator") || name.contains("ranging cape")
			|| (name.contains("max cape") && !name.contains("dizana"))) return 0.72;
		if (name.contains("attractor")) return 0.60;
		// A quiver's Ava upgrade is account-wide and has no visible item variant,
		// so assuming it here could materially understate cost.
		return 0;
	}

	private static boolean recoverableAmmo(String ammoName)
	{
		String name = NameMatcher.normalize(ammoName);
		return !name.contains("bolt rack") && !name.endsWith(" tar")
			&& !name.contains("chinchompa") && !name.contains("holy water");
	}

	private static void addMagicCost(List<CategoryCost> costs, LoadoutTier tier,
		ItemManager itemManager, long attacks, String methodName)
	{
		if (methodName == null || methodName.isEmpty()) return;
		GearRecommendation weapon = tier.get(EquipmentInventorySlot.WEAPON);
		String weaponName = weapon == null ? "" : NameMatcher.normalize(weapon.getItemName());
		RuneRecipe recipe = RuneRecipe.forMethod(methodName);
		if (recipe == null) return;
		long perCast = recipe.coinCost;
		for (RuneUse rune : recipe.runes)
		{
			if (suppliesRune(weaponName, rune.itemId)) continue;
			perCast += (long) rune.quantity * Math.max(0, itemManager.getItemPrice(rune.itemId));
		}
		long cost = attacks * perCast;
		if (cost > 0) costs.add(new CategoryCost("Combat casts", cost));
	}

	private static boolean suppliesRune(String weapon, int runeId)
	{
		if (runeId == ItemID.AIRRUNE)
			return has(weapon, "staff of air", "air battlestaff", "mystic air staff",
				"mist battlestaff", "mist staff", "dust battlestaff", "dust staff",
				"smoke battlestaff", "smoke staff");
		if (runeId == ItemID.WATERRUNE)
			return has(weapon, "staff of water", "water battlestaff", "mystic water staff",
				"mist battlestaff", "mist staff", "mud battlestaff", "mud staff",
				"steam battlestaff", "steam staff", "kodai wand");
		if (runeId == ItemID.EARTHRUNE)
			return has(weapon, "staff of earth", "earth battlestaff", "mystic earth staff",
				"dust battlestaff", "dust staff", "mud battlestaff", "mud staff",
				"lava battlestaff", "lava staff");
		if (runeId == ItemID.FIRERUNE)
			return has(weapon, "staff of fire", "fire battlestaff", "mystic fire staff",
				"smoke battlestaff", "smoke staff", "steam battlestaff", "steam staff",
				"lava battlestaff", "lava staff");
		return false;
	}

	private static boolean has(String value, String... tokens)
	{
		for (String token : tokens) if (value.contains(token)) return true;
		return false;
	}

	static String compactGp(long value)
	{
		if (value >= 1_000_000) return String.format(Locale.ENGLISH, "%.1fm", value / 1_000_000.0);
		if (value >= 1_000) return String.format(Locale.ENGLISH, "%.1fk", value / 1_000.0);
		return value + " gp";
	}

	private static final class CategoryCost
	{
		private final String category;
		private final long cost;
		private CategoryCost(String category, long cost) { this.category = category; this.cost = cost; }
		private long getCost() { return cost; }
	}

	private static final class RuneUse
	{
		private final int itemId;
		private final int quantity;
		private RuneUse(int itemId, int quantity) { this.itemId = itemId; this.quantity = quantity; }
	}

	private static final class RuneRecipe
	{
		private final List<RuneUse> runes = new ArrayList<>();
		private long coinCost;

		private RuneRecipe rune(int itemId, int quantity)
		{
			runes.add(new RuneUse(itemId, quantity));
			return this;
		}

		private RuneRecipe coins(long coins) { coinCost = coins; return this; }

		private static RuneRecipe forMethod(String methodName)
		{
			String method = NameMatcher.normalize(methodName);
			if (method.contains("warped sceptre"))
				return new RuneRecipe().rune(ItemID.CHAOSRUNE, 2).rune(ItemID.EARTHRUNE, 5);
			if (method.contains("trident of the swamp"))
				return new RuneRecipe().rune(ItemID.DEATHRUNE, 1).rune(ItemID.CHAOSRUNE, 1)
					.rune(ItemID.FIRERUNE, 5).rune(ItemID.SNAKEBOSS_SCALE, 1);
			if (method.contains("trident of the seas"))
				return new RuneRecipe().rune(ItemID.DEATHRUNE, 1).rune(ItemID.CHAOSRUNE, 1)
					.rune(ItemID.FIRERUNE, 5).coins(10);
			if (method.contains("sanguinesti staff"))
				return new RuneRecipe().rune(ItemID.BLOODRUNE, 3);
			if (method.contains("tumeken") && method.contains("shadow"))
				return new RuneRecipe().rune(ItemID.SOULRUNE, 2).rune(ItemID.CHAOSRUNE, 5);
			if (method.contains("ice barrage"))
				return new RuneRecipe().rune(ItemID.WATERRUNE, 6).rune(ItemID.DEATHRUNE, 4)
					.rune(ItemID.BLOODRUNE, 2);
			if (method.contains("ice burst"))
				return new RuneRecipe().rune(ItemID.WATERRUNE, 4).rune(ItemID.CHAOSRUNE, 2)
					.rune(ItemID.DEATHRUNE, 4);
			return elemental(method);
		}

		private static RuneRecipe elemental(String method)
		{
			int elementRune = method.contains("water") ? ItemID.WATERRUNE
				: method.contains("earth") ? ItemID.EARTHRUNE
				: method.contains("fire") ? ItemID.FIRERUNE : 0;
			int elementQuantity;
			RuneRecipe recipe = new RuneRecipe();
			if (method.contains("surge"))
			{
				recipe.rune(ItemID.AIRRUNE, 7).rune(ItemID.WRATHRUNE, 1);
				elementQuantity = 10;
			}
			else if (method.contains("wave"))
			{
				recipe.rune(ItemID.AIRRUNE, 5).rune(ItemID.BLOODRUNE, 1);
				elementQuantity = 7;
			}
			else if (method.contains("blast"))
			{
				recipe.rune(ItemID.AIRRUNE, 3).rune(ItemID.DEATHRUNE, 1);
				elementQuantity = method.contains("water") ? 3 : method.contains("earth") ? 4 : 5;
			}
			else if (method.contains("bolt"))
			{
				recipe.rune(ItemID.AIRRUNE, 2).rune(ItemID.CHAOSRUNE, 1);
				elementQuantity = method.contains("water") ? 2 : method.contains("earth") ? 3 : 4;
			}
			else if (method.contains("strike"))
			{
				recipe.rune(ItemID.AIRRUNE, 1).rune(ItemID.MINDRUNE, 1);
				elementQuantity = method.contains("water") ? 1 : method.contains("earth") ? 2 : 3;
			}
			else return null;
			if (elementRune != 0) recipe.rune(elementRune, elementQuantity);
			return recipe;
		}
	}
}

