		when(composition.getName()).thenReturn("Abyssal whip");
		when(itemManager.getItemStats(itemId)).thenReturn(itemStats);
		when(itemStats.isEquipable()).thenReturn(true);
		when(itemStats.getEquipment()).thenReturn(equipmentStats);
		when(supplyAdvisor.recommend(
			any(SlayerTaskProfile.class), any(GearStrategy.class), any(), anyInt(),
			any(Item[].class), any(Item[].class), anyBoolean()))
			.thenReturn(Collections.emptyList());

		Item item = new Item(itemId, 1);
		SlayerTaskProfile profile = TaskProfiles.find("Bloodveld").orElseThrow();
		new GearScorer(itemManager, supplyAdvisor).score(
			"Bloodveld", 100, profile,
			new Item[] {item, item, item},
			new Item[] {item},
			new Item[] {item},
			new Item[0],
			1, 99, 99, false, false, "", GearPriority.BALANCED,
			"", "", false, 0);

		verify(itemManager, times(1)).canonicalize(itemId);
		verify(itemManager, times(1)).getItemComposition(itemId);
		verify(itemManager, times(1)).getItemStats(itemId);
	}

	private static GearScorer.BankEquipment riskItem(
		int itemId,
		String name,
		EquipmentInventorySlot slot,
		int guidePrice,
		double score,
		boolean pinned)
	{
		return riskItem(itemId, name, slot, guidePrice, score, pinned, false);
	}

	private static GearScorer.BankEquipment riskItem(
		int itemId,
		String name,
		EquipmentInventorySlot slot,
		int guidePrice,
		double score,
		boolean pinned,
		boolean twoHanded)
	{
		ItemEquipmentStats stats = ItemEquipmentStats.builder()
			.slot(slot.getSlotIdx())
			.isTwoHanded(twoHanded)
			.build();
		GearScorer.BankEquipment item = new GearScorer.BankEquipment(
			itemId, itemId, name, slot, stats, true, false);
		item.guidePrice = guidePrice;
		item.score = score;
		item.pinned = pinned;
		return item;
	}

	private static GearScorer.BankEquipment equipment(
		int itemId,
		String name,
		EquipmentInventorySlot slot,
		ItemEquipmentStats stats)
	{
		return new GearScorer.BankEquipment(
			itemId, itemId, name, slot, stats, true, false);
	}

	private static GearScorer.BankEquipment weightedEquipment(
		int itemId,
		String name,
		EquipmentInventorySlot slot,
		double weightKg,
		double score,
		boolean twoHanded)
	{
		ItemEquipmentStats stats = ItemEquipmentStats.builder()
			.slot(slot.getSlotIdx())
			.isTwoHanded(twoHanded)
			.build();
		GearScorer.BankEquipment item = new GearScorer.BankEquipment(
			itemId, itemId, name, slot, stats, true, false, weightKg);
		item.score = score;
		return item;
	}

	private static String bestItem(
		GearScorer scorer,
		GearStrategy strategy,
		List<GearScorer.BankEquipment> equipment,
		EquipmentInventorySlot slot)
	{
		Map<EquipmentInventorySlot, List<GearScorer.BankEquipment>> candidates =
			scorer.buildCandidates(
				equipment,
				strategy,
				Collections.emptyList(),
				GearPriority.BALANCED,
				Collections.emptySet(),
				Collections.emptySet(),
				false,
				0);
		List<Map<EquipmentInventorySlot, GearRecommendation>> loadouts =
			scorer.buildCoherentLoadouts(
				1, candidates, strategy, Collections.emptyList(),
				Collections.emptySet(), false, 0);
		return loadouts.get(0).get(slot).getItemName();
	}

}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class InventoryCapacityPlannerTest
{
	private final InventoryCapacityPlanner planner = new InventoryCapacityPlanner();

	@Test
	public void optionalFoodIsReducedFirstToFitTheInventory()
	{
		List<GearRecommendation> gear = List.of(
			gear(1001, EquipmentInventorySlot.HEAD),
			gear(1002, EquipmentInventorySlot.BODY));
		List<SupplyRecommendation> supplies = List.of(
			supply("Anglerfish", "Food", false, 8, 8, 0, "items"),
			supply("Goading potion(4)", "Goading", false, 4, 4, 0, "doses"));

		GearRecommendations fitted = planner.apply(
			recommendations(gear, supplies),
			occupiedInventory(20),
			true,
			false);

		SupplyRecommendation food = supplyByCategory(fitted, "Food");
		SupplyRecommendation goading = supplyByCategory(fitted, "Goading");
		assertEquals(5, food.getRecommendedQuantity());
		assertEquals(8, food.getRequestedQuantity());
		assertTrue(food.isCapacityAdjusted());
		assertEquals(4, goading.getRecommendedQuantity());
		assertEquals(31, fitted.getInventoryPlan().getRequestedSlots());
		assertEquals(28, fitted.getInventoryPlan().getPlannedSlots());
		assertTrue(fitted.getInventoryPlan().fits());
		assertTrue(fitted.getInventoryPlan().wasTrimmed());
	}

	@Test
	public void requiredSuppliesAreNeverTrimmed()
	{
		SupplyRecommendation requiredPrayer = supply(
			"Prayer potion(4)", "Prayer", true, 8, 8, 0, "doses");

		GearRecommendations fitted = planner.apply(
			recommendations(Collections.emptyList(), List.of(requiredPrayer)),
			occupiedInventory(27),
			true,
			false);

		assertEquals(8, supplyByCategory(fitted, "Prayer").getRecommendedQuantity());
		assertFalse(supplyByCategory(fitted, "Prayer").isCapacityAdjusted());
		assertEquals(29, fitted.getInventoryPlan().getPlannedSlots());
		assertEquals(1, fitted.getInventoryPlan().getOverBy());
		assertFalse(fitted.getInventoryPlan().fits());
	}

	@Test
	public void packedPotionOnlyPlansTheRemainingPotionSlot()
	{
		SupplyRecommendation prayer = new SupplyRecommendation(
			2001,
			2001,
			"Prayer potion(4)",
			"Prayer",
			"Sustain",
			SupplyStatus.PACKED_BANKED,
			false,
			8,
			8,
			4,
			40,
			"doses");

		assertEquals(1, InventoryCapacityPlanner.additionalSlots(prayer));
		GearRecommendations fitted = planner.apply(
			recommendations(Collections.emptyList(), List.of(prayer)),
			new Item[]{new Item(2001, 1)},
			true,
			false);
		assertEquals(2, fitted.getInventoryPlan().getPlannedSlots());
	}

	@Test
	public void prepFocusCyclesThroughEveryView()
	{
		assertEquals(PrepFocusMode.MISSING, PrepFocusMode.ALL.next());
		assertEquals(PrepFocusMode.GEAR, PrepFocusMode.MISSING.next());
		assertEquals(PrepFocusMode.SUPPLIES, PrepFocusMode.GEAR.next());
		assertEquals(PrepFocusMode.ALL, PrepFocusMode.SUPPLIES.next());
	}

	private static GearRecommendations recommendations(
		List<GearRecommendation> gear,
		List<SupplyRecommendation> supplies)
	{
		Map<EquipmentInventorySlot, GearRecommendation> selected =
			new EnumMap<>(EquipmentInventorySlot.class);
		Map<EquipmentInventorySlot, List<GearRecommendation>> bySlot =
			new EnumMap<>(EquipmentInventorySlot.class);
		for (GearRecommendation recommendation : gear)
		{
			selected.put(recommendation.getSlot(), recommendation);
			bySlot.put(recommendation.getSlot(), List.of(recommendation));
		}

		List<LoadoutTier> tiers = selected.isEmpty()
			? Collections.emptyList()
			: List.of(new LoadoutTier(1, selected));
		return GearRecommendations.ready(
			"Greater demons",
			80,
			null,
			null,
			Collections.emptyList(),
			bySlot,
			tiers,
			supplies,
			new ReadinessReport(
				0,
				gear.size(),
				true,
				true,
				"Not required",
				0,
				supplies.size(),
				Collections.emptyList()),
			gear.size());
	}

	private static GearRecommendation gear(
		int itemId,
		EquipmentInventorySlot slot)
	{
		return GearRecommendation.builder()
			.itemId(itemId)
			.canonicalItemId(itemId)
			.itemName("Gear " + itemId)
			.slot(slot)
			.rank(1)
			.reason("Test")
			.banked(true)
			.packed(false)
			.build();
	}

	private static SupplyRecommendation supply(
		String itemName,
		String category,
		boolean required,
		int automatic,
		int recommended,
		int packed,
		String unit)
	{
		return new SupplyRecommendation(
			itemName.hashCode(),
			itemName.hashCode(),
			itemName,
			category,
			"Test",
			packed > 0 ? SupplyStatus.PACKED_BANKED : SupplyStatus.BANKED,
			required,
			automatic,
			recommended,
			packed,
			100,
			unit);
	}

	private static SupplyRecommendation supplyByCategory(
		GearRecommendations recommendations,
		String category)
	{
		return recommendations.getSupplies().stream()
			.filter(supply -> category.equals(supply.getCategory()))
			.findFirst()
			.orElseThrow();
	}

	private static Item[] occupiedInventory(int count)
	{
		List<Item> items = new ArrayList<>();
		for (int index = 0; index < count; index++)
		{
			items.add(new Item(10_000 + index, 1));
		}
		return items.toArray(new Item[0]);
	}
}

package com.freearcanes.slayergear;

import net.runelite.client.plugins.banktags.BankTag;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.tabs.Layout;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class InventorySetupBankTagStateTest
{
	@Test
	public void neutralizesAndRestoresOriginalLayout()
	{
		FakeBankTagsService service = new FakeBankTagsService();
		service.openBankTag("_invsetup_alpha", 0);
		InventorySetupBankTagState state = new InventorySetupBankTagState();

		assertTrue(state.captureActive(service));
		service.closeBankTag(); // Native search initialization closes the tag.
		state.reopenNeutralized(service);

		assertEquals("_invsetup_alpha", service.activeTag);
		assertNull(service.activeLayout);
		assertTrue((service.options & BankTagsService.OPTION_NO_LAYOUT) != 0);

		boolean restore = state.shouldRestore(service);
		service.closeBankTag(); // Best-in-Bank search reset closes the lease.
		state.restore(service, restore);

		assertEquals("_invsetup_alpha", service.activeTag);
		assertTrue(service.activeLayout != null);
		assertFalse((service.options & BankTagsService.OPTION_NO_LAYOUT) != 0);
	}

	@Test
	public void followsSetupSwitchWhileBestInBankIsOpen()
	{
		FakeBankTagsService service = new FakeBankTagsService();
		InventorySetupBankTagState state = new InventorySetupBankTagState();
		service.openBankTag("_invsetup_alpha", 0);
		state.captureActive(service);
		state.neutralizeActive(service);

		service.openBankTag("_invsetup_beta", 0);
		assertTrue(state.activeNeedsNeutralizing(service));
		state.neutralizeActive(service);

		assertEquals("_invsetup_beta", service.activeTag);
		assertNull(service.activeLayout);
		boolean restore = state.shouldRestore(service);
		service.closeBankTag();
		state.restore(service, restore);
		assertEquals("_invsetup_beta", service.activeTag);
		assertTrue(service.activeLayout != null);
	}

	@Test
	public void doesNotResurrectDeselectedSetup()
	{
		FakeBankTagsService service = new FakeBankTagsService();
		InventorySetupBankTagState state = new InventorySetupBankTagState();
		service.openBankTag("_invsetup_alpha", 0);
		state.captureActive(service);
		state.neutralizeActive(service);

		service.closeBankTag();
		boolean restore = state.shouldRestore(service);
		state.restore(service, restore);

		assertFalse(restore);
		assertNull(service.activeTag);
	}

	@Test
	public void preservesClassicFilteringPreference()
	{
		FakeBankTagsService service = new FakeBankTagsService();
		InventorySetupBankTagState state = new InventorySetupBankTagState();
		service.openBankTag(
			"_invsetup_alpha", BankTagsService.OPTION_NO_LAYOUT);
		state.captureActive(service);

		boolean restore = state.shouldRestore(service);
		service.closeBankTag();
		state.restore(service, restore);

		assertNull(service.activeLayout);
		assertTrue((service.options & BankTagsService.OPTION_NO_LAYOUT) != 0);
	}

	@Test
	public void followsSameSetupLayoutPreferenceChange()
	{
		FakeBankTagsService service = new FakeBankTagsService();
		InventorySetupBankTagState state = new InventorySetupBankTagState();
		service.openBankTag("_invsetup_alpha", 0);
		state.captureActive(service);
		state.neutralizeActive(service);
		state.updateLayoutPreference(false);

		boolean restore = state.shouldRestore(service);
		service.closeBankTag();
		state.restore(service, restore);

		assertNull(service.activeLayout);
		assertTrue((service.options & BankTagsService.OPTION_NO_LAYOUT) != 0);
	}

	@Test
	public void doesNotReplaceNormalBankTag()
	{
		FakeBankTagsService service = new FakeBankTagsService();
		InventorySetupBankTagState state = new InventorySetupBankTagState();
		service.openBankTag("_invsetup_alpha", 0);
		state.captureActive(service);
		state.neutralizeActive(service);
		service.openBankTag("normal-tag", 0);

		boolean restore = state.shouldRestore(service);
		state.restore(service, restore);

		assertFalse(restore);
		assertEquals("normal-tag", service.activeTag);
	}

	private static final class FakeBankTagsService implements BankTagsService
	{
		private String activeTag;
		private Layout activeLayout;
		private int options;

		@Override
		public void openBankTag(String tag, int options)
		{
			this.activeTag = tag;
			this.options = options;
			this.activeLayout = (options & OPTION_NO_LAYOUT) == 0
				? new Layout(tag) : null;
		}

		@Override
		public void closeBankTag()
		{
			activeTag = null;
			activeLayout = null;
			options = 0;
		}

		@Override
		public String getActiveTag()
		{
			return activeTag;
		}

		@Override
		public BankTag getActiveBankTag()
		{
			return null;
		}

		@Override
		public Layout getActiveLayout()
		{
			return activeLayout;
		}
	}
}

package com.freearcanes.slayergear;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class LoadoutCombatEffectsTest
{
	@Test
	public void completeVoidSetsUseStyleAndEliteSpecificEffects()
	{
		Map<EquipmentInventorySlot, GearRecommendation> ranged = voidSet(
			"Void ranger helm (or)", "Elite void top (or)", "Elite void robe (or)");
		LoadoutCombatEffects rangedEffects = LoadoutCombatEffects.resolve(ranged,
			GearStrategy.builder().combatStyle(CombatStyle.RANGED).build(), "Magic shortbow (i)");
		assertEquals(1.10, rangedEffects.getEffectiveAccuracy(), 0.000001);
		assertEquals(1.125, rangedEffects.getEffectiveStrength(), 0.000001);

		Map<EquipmentInventorySlot, GearRecommendation> magic = voidSet(
			"Void mage helm", "Elite void top", "Elite void robe");
		LoadoutCombatEffects magicEffects = LoadoutCombatEffects.resolve(magic,
			GearStrategy.builder().combatStyle(CombatStyle.MAGIC).build(), "Trident of the swamp");
		assertEquals(1.45, magicEffects.getEffectiveAccuracy(), 0.000001);
		assertEquals(1.05, magicEffects.getFinalDamage(), 0.000001);
	}

	@Test
	public void incompleteOrWrongStyleVoidGetsNoEffect()
	{
		Map<EquipmentInventorySlot, GearRecommendation> wrong = voidSet(
			"Void melee helm", "Void knight top", "Void knight robe");
		wrong.remove(EquipmentInventorySlot.GLOVES);
		LoadoutCombatEffects effects = LoadoutCombatEffects.resolve(wrong,
			GearStrategy.builder().combatStyle(CombatStyle.RANGED).build(), "Yew shortbow");
		assertEquals(1.0, effects.getEffectiveAccuracy(), 0.000001);
		assertEquals(1.0, effects.getEffectiveStrength(), 0.000001);
	}

	@Test
	public void crystalPiecesApplyOnlyToCompatibleCrystalBows()
	{
		Map<EquipmentInventorySlot, GearRecommendation> loadout = new EnumMap<>(EquipmentInventorySlot.class);
		loadout.put(EquipmentInventorySlot.HEAD, item(1, "Crystal helm (inactive)", EquipmentInventorySlot.HEAD));
		loadout.put(EquipmentInventorySlot.BODY, item(2, "Crystal body (c)", EquipmentInventorySlot.BODY));
		loadout.put(EquipmentInventorySlot.LEGS, item(3, "Crystal legs", EquipmentInventorySlot.LEGS));
		GearStrategy ranged = GearStrategy.builder().combatStyle(CombatStyle.RANGED).build();

		LoadoutCombatEffects bowfa = LoadoutCombatEffects.resolve(
			loadout, ranged, "Bow of faerdhinen (c)");
		assertEquals(1.30, bowfa.getFinalAccuracy(), 0.000001);
		assertEquals(1.15, bowfa.getFinalDamage(), 0.000001);
		assertEquals(1.0, LoadoutCombatEffects.resolve(
			loadout, ranged, "Twisted bow").getFinalDamage(), 0.000001);
	}

	@Test
	public void inquisitorCountsPiecesCrushStyleAndMaceEnhancement()
	{
		Map<EquipmentInventorySlot, GearRecommendation> loadout = new EnumMap<>(EquipmentInventorySlot.class);
		loadout.put(EquipmentInventorySlot.HEAD, item(1, "Inquisitor's great helm", EquipmentInventorySlot.HEAD));
		loadout.put(EquipmentInventorySlot.BODY, item(2, "Inquisitor's hauberk", EquipmentInventorySlot.BODY));
		loadout.put(EquipmentInventorySlot.LEGS, item(3, "Inquisitor's plateskirt", EquipmentInventorySlot.LEGS));
		GearStrategy crush = GearStrategy.builder().combatStyle(CombatStyle.MELEE)
			.attackType(AttackType.CRUSH).build();

		assertEquals(1.025, LoadoutCombatEffects.resolve(
			loadout, crush, "Scythe of vitur").getFinalDamage(), 0.000001);
		assertEquals(1.075, LoadoutCombatEffects.resolve(
			loadout, crush, "Inquisitor's mace").getFinalDamage(), 0.000001);
		GearStrategy slash = GearStrategy.builder().combatStyle(CombatStyle.MELEE)
			.attackType(AttackType.SLASH).build();
		assertEquals(1.0, LoadoutCombatEffects.resolve(
			loadout, slash, "Inquisitor's mace").getFinalDamage(), 0.000001);
	}

	private static Map<EquipmentInventorySlot, GearRecommendation> voidSet(
		String helm, String body, String legs)
	{
		Map<EquipmentInventorySlot, GearRecommendation> result = new EnumMap<>(EquipmentInventorySlot.class);
		result.put(EquipmentInventorySlot.HEAD, item(1, helm, EquipmentInventorySlot.HEAD));
		result.put(EquipmentInventorySlot.BODY, item(2, body, EquipmentInventorySlot.BODY));
		result.put(EquipmentInventorySlot.LEGS, item(3, legs, EquipmentInventorySlot.LEGS));
		result.put(EquipmentInventorySlot.GLOVES,
			item(4, "Void knight gloves (or)", EquipmentInventorySlot.GLOVES));
		return result;
	}

	private static GearRecommendation item(int id, String name, EquipmentInventorySlot slot)
	{
		return GearRecommendation.builder().itemId(id).canonicalItemId(id)
			.itemName(name).slot(slot).build();
	}
}

package com.freearcanes.slayergear;

