package com.freearcanes.slayergear;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class PotionDoseEstimatorTest
{
	private final SlayerGearAdvisorConfig noRegen = new SlayerGearAdvisorConfig()
	{
		@Override
		public boolean usePrayerRegen() { return false; }
	};

	@Test
	public void everyManualBossHasAnExplicitTripProfile()
	{
		for (String boss : BossSlayerCatalog.names())
		{
			assertTrue(boss, PotionDoseEstimator.hasEncounterProfile(boss));
		}
	}

	@Test
	public void prayerRestoreUsesThePlayersActualLevelAndPotionType()
	{
		assertEquals(31, PotionDoseEstimator.prayerRestorePerDose(99, false));
		assertEquals(32, PotionDoseEstimator.prayerRestorePerDose(99, true));
		assertEquals(24, PotionDoseEstimator.prayerRestorePerDose(70, false));
		assertEquals(25, PotionDoseEstimator.prayerRestorePerDose(70, true));
	}

	@Test
	public void araxxorCalibrationScalesWithKillsPrayerLevelAndGearBonus()
	{
		SlayerTaskProfile profile = TaskProfiles.find("Araxxor").orElseThrow();
		GearStrategy strategy = profile.getStrategies().get(0);

		assertEquals(11, estimatePrayer(profile, strategy,
			new PotionEstimationContext("Araxxor", 99, 10, 103), 3, noRegen));
		assertEquals(5, estimatePrayer(profile, strategy,
			new PotionEstimationContext("Araxxor", 99, 0, 103), 1, noRegen));
		assertEquals(3, estimatePrayer(profile, strategy,
			new PotionEstimationContext("Araxxor", 99, 30, 103), 1, noRegen));
		assertEquals(5, estimatePrayer(profile, strategy,
			new PotionEstimationContext("Araxxor", 70, 10, 103), 1, noRegen));
	}

	@Test
	public void encounterTripCapsPreventFullBossAssignmentsFromFillingInventory()
	{
		SlayerTaskProfile profile = TaskProfiles.find("Alchemical Hydra").orElseThrow();
		GearStrategy strategy = profile.getStrategies().get(0);
		int doses = estimatePrayer(profile, strategy,
			new PotionEstimationContext("Alchemical Hydra", 99, 10, 120),
			150, noRegen);

		assertEquals(34, doses); // ten-kill trip at 3.33 doses/kill
	}

	@Test
	public void prayerRegenerationReducesRatherThanDuplicatesRestoreDemand()
	{
		SlayerTaskProfile profile = TaskProfiles.find("Alchemical Hydra").orElseThrow();
		GearStrategy strategy = profile.getStrategies().get(0);
		PotionEstimationContext context =
			new PotionEstimationContext("Alchemical Hydra", 99, 10, 120);
		SlayerGearAdvisorConfig withRegen = new SlayerGearAdvisorConfig() { };

		int without = estimatePrayer(profile, strategy, context, 10, noRegen);
		int with = estimatePrayer(profile, strategy, context, 10, withRegen);
		int regen = PotionDoseEstimator.estimate("Prayer regen", 10,
			profile, strategy, context, withRegen);

		assertEquals(34, without);
		assertEquals(3, regen);
		assertTrue(with < without);
	}

	@Test
	public void timedEffectsFollowCombatDurationInsteadOfRawKillCount()
	{
		SlayerTaskProfile profile = TaskProfiles.find("Greater demons").orElseThrow();
		GearStrategy strategy = profile.getStrategies().get(0);
		PotionEstimationContext context =
			new PotionEstimationContext("Greater demons", 80, 10, 100);

		assertEquals(2, PotionDoseEstimator.estimate("Combat boost", 5,
			profile, strategy, context, noRegen));
		assertEquals(2, PotionDoseEstimator.estimate("Goading", 5,
			profile, strategy, context, noRegen));
		assertEquals(2, PotionDoseEstimator.estimate("Antifire", 5,
			profile, strategy, context, noRegen));
	}

	@Test
	public void rawBossDpsCannotEraseMechanicAndTransitionTime()
	{
		SlayerTaskProfile profile = TaskProfiles.find("Araxxor").orElseThrow();
		GearStrategy strategy = profile.getStrategies().get(0);
		PotionEstimationContext unrealisticallyShortRawTtk =
			new PotionEstimationContext("Araxxor", 99, 10, 40);

		assertEquals(4, PotionDoseEstimator.estimate("Combat boost", 10,
			profile, strategy, unrealisticallyShortRawTtk, noRegen));
	}

	@Test
	public void waveEncountersUseWholeEncounterSupplyBudgets()
	{
		SlayerTaskProfile jad = TaskProfiles.find("TzTok-Jad").orElseThrow();
		SlayerTaskProfile zuk = TaskProfiles.find("TzKal-Zuk").orElseThrow();
		assertEquals(56, estimatePrayer(jad, jad.getStrategies().get(0),
			new PotionEstimationContext("TzTok-Jad", 99, 10, 0), 1, noRegen));
		assertEquals(40, estimatePrayer(zuk, zuk.getStrategies().get(0),
			new PotionEstimationContext("TzKal-Zuk", 99, 10, 0), 1, noRegen));
	}

	private static int estimatePrayer(SlayerTaskProfile profile,
		GearStrategy strategy, PotionEstimationContext context, int kills,
		SlayerGearAdvisorConfig config)
	{
		return PotionDoseEstimator.estimate(
			"Prayer", kills, profile, strategy, context, config);
	}
}

package com.freearcanes.slayergear;

import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

public class PrayerPriorityTest
{
	@Test
	public void prayerFirstPrefersPrayerArmorOverSmallStrengthBonus()
	{
		GearStrategy strategy = TaskProfiles.find("Bloodveld")
			.orElseThrow()
			.getStrategies()
			.stream()
			.filter(s -> s.getCombatStyle() == CombatStyle.MELEE)
			.findFirst()
			.orElseThrow();

		ItemEquipmentStats proselyte = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.BODY.getSlotIdx())
			.prayer(8)
			.build();

		ItemEquipmentStats fighterTorso = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.BODY.getSlotIdx())
			.str(4)
			.build();

		double prayerProselyte = GearScorer.scoreStats(
			strategy, "Proselyte hauberk", EquipmentInventorySlot.BODY,
			proselyte, GearPriority.PRAYER_FIRST);
		double prayerTorso = GearScorer.scoreStats(
			strategy, "Fighter torso", EquipmentInventorySlot.BODY,
			fighterTorso, GearPriority.PRAYER_FIRST);

		assertTrue(prayerProselyte > prayerTorso);
	}

	@Test
	public void balancedModeKeepsCurrentOffensivePreference()
	{
		GearStrategy strategy = TaskProfiles.find("Bloodveld")
			.orElseThrow()
			.getStrategies()
			.stream()
			.filter(s -> s.getCombatStyle() == CombatStyle.MELEE)
			.findFirst()
			.orElseThrow();

		ItemEquipmentStats prayerBody = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.BODY.getSlotIdx())
			.prayer(8)
			.build();

		ItemEquipmentStats strengthBody = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.BODY.getSlotIdx())
			.str(4)
			.build();

		double prayerScore = GearScorer.scoreStats(
			strategy, "Prayer body", EquipmentInventorySlot.BODY,
			prayerBody, GearPriority.BALANCED);
		double strengthScore = GearScorer.scoreStats(
			strategy, "Strength body", EquipmentInventorySlot.BODY,
			strengthBody, GearPriority.BALANCED);

		assertTrue(strengthScore > prayerScore);
	}

	@Test
	public void prayerFirstStillProtectsGargoyleTargetWeaponLogic()
	{
		GearStrategy gargoyle = TaskProfiles.find("Gargoyles")
			.orElseThrow()
			.getStrategies()
			.get(0);

		ItemEquipmentStats granite = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.WEAPON.getSlotIdx())
			.acrush(57)
			.str(56)
			.aspeed(4)
			.build();

		ItemEquipmentStats halberd = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.WEAPON.getSlotIdx())
			.astab(85)
			.aslash(92)
			.str(118)
			.aspeed(7)
			.build();

		double graniteScore = GearScorer.scoreStats(
			gargoyle, "Granite hammer", EquipmentInventorySlot.WEAPON,
			granite, GearPriority.PRAYER_FIRST);
		double halberdScore = GearScorer.scoreStats(
			gargoyle, "Crystal halberd", EquipmentInventorySlot.WEAPON,
			halberd, GearPriority.PRAYER_FIRST);

		assertTrue(graniteScore > halberdScore);
	}

	@Test
	public void prayerFirstPrefersHigherPrayerAccessory()
	{
		GearStrategy strategy = TaskProfiles.find("Vampyres")
			.orElseThrow()
			.getStrategies()
			.get(0);

		ItemEquipmentStats highPrayer = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.RING.getSlotIdx())
			.prayer(8)
			.build();

		ItemEquipmentStats lowerPrayer = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.RING.getSlotIdx())
			.prayer(4)
			.dmagic(20)
			.build();

		double high = GearScorer.scoreStats(
			strategy, "Ring of the gods (i)", EquipmentInventorySlot.RING,
			highPrayer, GearPriority.PRAYER_FIRST);
		double low = GearScorer.scoreStats(
			strategy, "Ring of suffering (ri)", EquipmentInventorySlot.RING,
			lowerPrayer, GearPriority.PRAYER_FIRST);

		assertTrue(high > low);
	}
}

package com.freearcanes.slayergear;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RangedAmmoPolicyTest
{
	@Test
	public void specialCrossbowsOnlyAcceptTheirOwnAmmunition()
	{
		compatible("Hunters' sunlight crossbow", "Moonlight antler bolts");
		incompatible("Hunters' sunlight crossbow", "Diamond bolts (e)");
		compatible("Hunters' crossbow", "Long kebbit bolts");
		incompatible("Hunters' crossbow", "Rune bolts");
		compatible("Karil's crossbow", "Bolt rack");
		incompatible("Karil's crossbow", "Diamond bolts (e)");
		compatible("Dorgeshuun crossbow", "Bone bolts");
		compatible("Dorgeshuun crossbow", "Iron bolts");
		incompatible("Dorgeshuun crossbow", "Opal bolts (e)");
		incompatible("Dorgeshuun crossbow", "Mithril bolts");
	}

	@Test
	public void standardCrossbowsEnforceMetalAndGemTiers()
	{
		compatible("Bronze crossbow", "Opal bolts (e)");
		incompatible("Bronze crossbow", "Iron bolts");
		compatible("Adamant crossbow", "Diamond bolts (e)");
		incompatible("Adamant crossbow", "Runite bolts");
		compatible("Rune crossbow", "Onyx bolts (e)");
		compatible("Rune crossbow", "Amethyst broad bolts");
		incompatible("Rune crossbow", "Diamond dragon bolts (e)");
		compatible("Dragon hunter crossbow", "Diamond dragon bolts (e)");
	}

	@Test
	public void bowsEnforceArrowTiersAndSpecialAmmunition()
	{
		compatible("Shortbow", "Iron arrow");
		incompatible("Shortbow", "Steel arrow");
		compatible("Willow shortbow", "Mithril fire arrow");
		incompatible("Willow shortbow", "Adamant arrow");
		compatible("Bone shortbow", "Rune arrow");
		compatible("Bone shortbow", "Broad arrows");
		incompatible("Bone shortbow", "Amethyst arrow");
		incompatible("Willow shortbow", "Broad arrows");
		compatible("Magic shortbow (i)", "Amethyst arrow");
		incompatible("Magic shortbow (i)", "Dragon arrow");
		compatible("Twisted bow", "Dragon arrow");
		compatible("Training bow", "Training arrows");
		incompatible("Training bow", "Bronze arrow");
		compatible("Ogre bow", "Mithril brutal");
		incompatible("Ogre bow", "Adamant brutal");
		compatible("Comp ogre bow", "Rune brutal");
		incompatible("Comp ogre bow", "Rune arrow");
	}

	@Test
	public void weaponFamiliesUseTheirExactAmmoOrInternalCharges()
	{
		compatible("Eclipse atlatl", "Atlatl dart");
		incompatible("Eclipse atlatl", "Dragon dart");
		compatible("Heavy ballista", "Dragon javelin");
		compatible("Swamp lizard", "Guam tar");
		compatible("Orange salamander", "Marrentill tar");
		compatible("Red salamander", "Tarromin tar");
		compatible("Black salamander", "Harralander tar");
		compatible("Tecu salamander", "Irit tar");
		incompatible("Black salamander", "Irit tar");

		assertFalse(RangedAmmoPolicy.usesAmmoSlot("Webweaver bow"));
		assertFalse(RangedAmmoPolicy.usesAmmoSlot("Craw's bow"));
		assertFalse(RangedAmmoPolicy.usesAmmoSlot("Tonalztics of ralos"));
		assertFalse(RangedAmmoPolicy.usesAmmoSlot("Toxic blowpipe"));
		assertTrue(RangedAmmoPolicy.usesAmmoSlot("Venator bow"));
	}

	@Test
	public void visibleEmptyInactiveAndUnchargedWeaponsAreRejected()
	{
		assertFalse(RangedAmmoPolicy.isUsableWeapon("Toxic blowpipe (empty)"));
		assertFalse(RangedAmmoPolicy.isUsableWeapon("Camphor blowpipe (empty)"));
		assertFalse(RangedAmmoPolicy.isUsableWeapon("Ironwood blowpipe (empty)"));
		assertFalse(RangedAmmoPolicy.isUsableWeapon("Rosewood blowpipe (empty)"));
		assertFalse(RangedAmmoPolicy.isUsableWeapon("Webweaver bow (u)"));
		assertFalse(RangedAmmoPolicy.isUsableWeapon("Craw's bow (u)"));
		assertFalse(RangedAmmoPolicy.isUsableWeapon("Venator bow (uncharged)"));
		assertFalse(RangedAmmoPolicy.isUsableWeapon("Tonalztics of ralos (uncharged)"));
		assertFalse(RangedAmmoPolicy.isUsableWeapon("Crystal bow (inactive)"));
		assertFalse(RangedAmmoPolicy.isUsableWeapon("Bow of faerdhinen (inactive)"));
		assertFalse(RangedAmmoPolicy.isUsableWeapon("Morrigan's javelin (bh)(inactive)"));
		assertTrue(RangedAmmoPolicy.isUsableWeapon("Webweaver bow"));
	}

	private static void compatible(String weapon, String ammo)
	{
		assertTrue(weapon + " should accept " + ammo, RangedAmmoPolicy.isCompatible(weapon, ammo));
	}

	private static void incompatible(String weapon, String ammo)
	{
		assertFalse(weapon + " should reject " + ammo, RangedAmmoPolicy.isCompatible(weapon, ammo));
	}
}

