package com.freearcanes.slayergear;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SystemWideScoringAndPrepTest
{
	private final SmartSupplyAdvisor advisor =
		new SmartSupplyAdvisor(null, new SlayerGearAdvisorConfig() {});

	@Test
	public void baselineDefenceIsACompleteButSmallTieBreaker()
	{
		GearStrategy ordinary = GearStrategy.builder()
			.name("Ordinary melee")
			.combatStyle(CombatStyle.MELEE)
			.build();
		ItemEquipmentStats offensive = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.BODY.getSlotIdx())
			.str(4)
			.build();
		ItemEquipmentStats defensive = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.BODY.getSlotIdx())
			.dstab(70)
			.dslash(70)
			.dcrush(70)
			.drange(70)
			.dmagic(70)
			.build();
		ItemEquipmentStats rangedDefence = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.BODY.getSlotIdx())
			.drange(40)
			.build();

		assertTrue(GearScorer.scoreStats(ordinary, "Strength body",
			EquipmentInventorySlot.BODY, offensive)
			> GearScorer.scoreStats(ordinary, "Tank body",
				EquipmentInventorySlot.BODY, defensive));
		assertTrue(GearScorer.scoreStats(ordinary, "Ranged defence body",
			EquipmentInventorySlot.BODY, rangedDefence)
			> GearScorer.scoreStats(ordinary, "No-stat body",
				EquipmentInventorySlot.BODY, ItemEquipmentStats.builder()
					.slot(EquipmentInventorySlot.BODY.getSlotIdx()).build()));
	}

	@Test
	public void explicitIncomingMagicContextChangesOnlyThatMethodsTieBreaker()
	{
		GearStrategy ordinary = GearStrategy.builder()
			.name("Ordinary melee")
			.combatStyle(CombatStyle.MELEE)
			.build();
		GearStrategy magicHeavy = GearStrategy.builder()
			.name("Magic-heavy melee")
			.combatStyle(CombatStyle.MELEE)
			.magicDefenceWeight(0.28)
			.build();
		ItemEquipmentStats physicalTank = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.BODY.getSlotIdx())
			.dstab(100)
			.dslash(100)
			.dcrush(100)
			.build();
		ItemEquipmentStats magicTank = ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.BODY.getSlotIdx())
			.dmagic(80)
			.build();

		assertTrue(GearScorer.scoreStats(ordinary, "Physical tank",
			EquipmentInventorySlot.BODY, physicalTank)
			> GearScorer.scoreStats(ordinary, "Magic tank",
				EquipmentInventorySlot.BODY, magicTank));
		assertTrue(GearScorer.scoreStats(magicHeavy, "Magic tank",
			EquipmentInventorySlot.BODY, magicTank)
			> GearScorer.scoreStats(magicHeavy, "Physical tank",
				EquipmentInventorySlot.BODY, physicalTank));
	}

	@Test
	public void knownMagicAttackingMeleeMethodsOptIntoExtraMagicDefence()
	{
		for (String task : new String[]{
			"Aberrant spectres", "Aquanites", "Bloodveld", "Jellies", "Suqahs", "Waterfiends"})
		{
			SlayerTaskProfile profile = TaskProfiles.find(task).orElseThrow();
			assertTrue(task + " lacks a context-aware Magic-defence melee method",
				profile.getStrategies().stream().anyMatch(strategy ->
					strategy.getCombatStyle() == CombatStyle.MELEE
						&& strategy.getMagicDefenceWeight() > 0));
		}

		SlayerTaskProfile kalphites = TaskProfiles.find("Kalphites").orElseThrow();
		assertFalse(kalphites.getStrategies().stream().anyMatch(strategy ->
			strategy.getMagicDefenceWeight() > 0));
	}

	@Test
	public void everyCuratedTaskStrategyHasVisibleCorePreparation()
	{
		Set<SlayerTaskProfile> profiles = new HashSet<>(TaskProfiles.catalogSnapshot().values());
		for (SlayerTaskProfile profile : profiles)
		{
			for (GearStrategy strategy : profile.getStrategies())
			{
				Set<String> categories = categories(profile, strategy, null);
				assertTrue(profile.getKey() + "/" + strategy.getName() + " lacks Prayer prep",
					categories.contains("Prayer"));
				assertTrue(profile.getKey() + "/" + strategy.getName() + " lacks Food prep",
					categories.contains("Food"));
				assertTrue(profile.getKey() + "/" + strategy.getName() + " lacks Run energy prep",
					categories.contains("Run energy"));
				assertTrue(profile.getKey() + "/" + strategy.getName() + " lacks Travel prep",
					categories.contains("Travel"));
				assertTrue(profile.getKey() + "/" + strategy.getName() + " lacks style boost",
					categories.contains(boostCategory(strategy)));
			}
		}
	}

	@Test
	public void genericSlayerMasterTasksAlsoReceiveCorePreparation()
	{
		for (List<String> assignments : SlayerMasterCatalog.allAssignments().values())
		{
			for (String task : assignments)
			{
				SlayerTaskProfile profile = TaskProfiles.find(task).orElseThrow();
				GearStrategy strategy = profile.getStrategies().get(0);
				Set<String> categories = categories(profile, strategy, null);
				assertTrue(task + " lacks Food prep", categories.contains("Food"));
				assertTrue(task + " lacks Prayer prep", categories.contains("Prayer"));
				assertTrue(task + " lacks Travel prep", categories.contains("Travel"));
			}
		}
	}

	@Test
	public void locationAndMonsterHazardsLayerOntoCorePreparation()
	{
		SlayerTaskProfile crawler = TaskProfiles.find(
			"Cave crawlers", "Lumbridge Swamp Caves").orElseThrow();
		Set<String> cave = categories(crawler, crawler.getStrategies().get(0),
			"Lumbridge Swamp Caves");
		assertTrue(cave.contains("Poison protection"));
		assertTrue(cave.contains("Light source"));
		assertTrue(cave.contains("Light backup"));
		assertTrue(cave.contains("Cave access"));

		SlayerTaskProfile lizardmen = TaskProfiles.find("Lizardmen").orElseThrow();
		assertTrue(categories(lizardmen, lizardmen.getStrategies().get(0), null)
			.contains("Poison protection"));

		SlayerTaskProfile greenDragons = TaskProfiles.find("Green dragons").orElseThrow();
		assertTrue(categories(greenDragons, greenDragons.getStrategies().get(0), null)
			.contains("Antifire"));

		SlayerTaskProfile lizards = TaskProfiles.find("Lizards").orElseThrow();
		assertTrue(categories(lizards, lizards.getStrategies().get(0), null)
			.contains("Desert hydration"));

		SlayerTaskProfile brineRats = TaskProfiles.find("Brine rats").orElseThrow();
		assertTrue(categories(brineRats, brineRats.getStrategies().get(0), null)
			.contains("Cave access"));

		SlayerTaskProfile kalphites = TaskProfiles.find("Kalphites").orElseThrow();
		assertFalse(categories(kalphites, kalphites.getStrategies().get(0), null)
			.contains("Cave access"));
		assertTrue(categories(kalphites, kalphites.getStrategies().get(0), "Kalphite Lair")
			.contains("Cave access"));
	}

	@Test
	public void corePreparationRemainsNonBlockingWhenItemsAreUnowned()
	{
		SlayerTaskProfile profile = TaskProfiles.find("Greater demons").orElseThrow();
		GearStrategy strategy = profile.getStrategies().get(0);
		List<SupplyRecommendation> recommendations = advisor.recommend(
			profile, strategy, 80, null, null);
		for (String category : new String[]{"Combat boost", "Prayer", "Food", "Run energy", "Travel"})
		{
			SupplyRecommendation supply = recommendations.stream()
				.filter(item -> category.equals(item.getCategory()))
				.findFirst()
				.orElseThrow(() -> new AssertionError("Missing visible prep category: " + category));
			assertFalse(category + " must remain optional", supply.isRequired());
		}
	}

	private Set<String> categories(
		SlayerTaskProfile profile,
		GearStrategy strategy,
		String assignedLocation)
	{
		return advisor.buildRules(profile, strategy, assignedLocation).stream()
			.map(SmartSupplyAdvisor.SupplyRule::getCategory)
			.collect(Collectors.toSet());
	}

	private static String boostCategory(GearStrategy strategy)
	{
		switch (strategy.getCombatStyle())
		{
			case MAGIC:
				return "Magic boost";
			case RANGED:
				return "Ranged boost";
			default:
				return "Combat boost";
		}
	}
}

package com.freearcanes.slayergear;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class TargetDefenceCatalogTest
{
	@Test
	public void bundledDatasetHasAValidHeaderAndEveryRowHasSixteenColumns() throws Exception
	{
		String resource = "/com/freearcanes/slayergear/slayer-targets.tsv";
		try (InputStream stream = TargetDefenceCatalogTest.class.getResourceAsStream(resource))
		{
			assertTrue(stream != null);
			try (BufferedReader reader = new BufferedReader(
				new InputStreamReader(stream, StandardCharsets.UTF_8)))
			{
				String line;
				boolean foundHeader = false;
				while ((line = reader.readLine()) != null)
				{
					if (!line.isEmpty() && line.charAt(0) == '\uFEFF') line = line.substring(1);
					if (line.isEmpty() || line.startsWith("#")) continue;
					String[] fields = line.split("\t", -1);
					assertEquals("Malformed dataset row: " + line, 16, fields.length);
					if (!foundHeader)
					{
						assertEquals("name", fields[0]);
						assertEquals("version", fields[1]);
						foundHeader = true;
					}
				}
				assertTrue("Dataset header missing", foundHeader);
			}
		}
	}

	@Test
	public void resolvesPluralTaskAndDeduplicatesIdenticalLocationVariants()
	{
		List<TargetDefence> targets = TargetDefenceCatalog.find("Abyssal demons", "abyssal-demons");
		assertEquals(1, targets.size());
		assertEquals("Abyssal demon", targets.get(0).getName());
	}

	@Test
	public void fossilIslandWyvernsPreserveDifferentDefenceVariants()
	{
		List<TargetDefence> targets = TargetDefenceCatalog.find(
			"Fossil Island wyverns", "fossil-island-wyverns");
		assertTrue(targets.size() >= 3);
	}

	@Test
	public void targetDatasetProvidesCombatIntelligenceFields()
	{
		TargetDefence abyssal = TargetDefenceCatalog.find(
			"Abyssal demons", "abyssal-demons").get(0);
		assertEquals(150, abyssal.getHitpoints());
		assertTrue(abyssal.hasAttribute("demon"));
		assertTrue(abyssal.getSize() >= 1);
	}

	@Test
	public void unknownAssignmentDoesNotInventTargetStats()
	{
		assertTrue(TargetDefenceCatalog.find("Unknown thing", "unknown-thing").isEmpty());
	}

	@Test
	public void resolvesDifferentPluralForms()
	{
		assertTrue(!TargetDefenceCatalog.find("Aviansies", "aviansies").isEmpty());
		assertTrue(!TargetDefenceCatalog.find("Zombies", "zombies").isEmpty());
		assertTrue(!TargetDefenceCatalog.find("Elves", "elves").isEmpty());
	}

	@Test
	public void resolvesMostDistinctCuratedTaskProfiles()
	{
		Set<String> checked = new HashSet<>();
		int resolved = 0;
		for (SlayerTaskProfile profile : TaskProfiles.catalogSnapshot().values())
		{
			if (checked.add(profile.getKey()) && !TargetDefenceCatalog.find(
				profile.getDisplayName(), profile.getKey()).isEmpty())
			{
				resolved++;
			}
		}
		assertTrue("Only resolved " + resolved + " curated target families", resolved >= 45);
	}

	@Test
	public void explicitlyNamedBossStrategyOverridesBroadAssignmentTarget()
	{
		GearStrategy araxxor = GearStrategy.builder().name("Araxxor - Crush melee").build();
		List<TargetDefence> targets = TargetDefenceCatalog.find(
			"Araxytes", "araxytes", araxxor);
		assertTrue(!targets.isEmpty());
		assertEquals("Araxxor", targets.get(0).getName());
	}
}

package com.freearcanes.slayergear;

import java.util.Collections;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class TaskConsumptionTrackerTest
{
	@Test
	public void reportsObservedDoseUseKillsAndElapsedTime()
	{
		ItemManager itemManager = mock(ItemManager.class);
		ItemComposition fourDose = mock(ItemComposition.class);
		ItemComposition twoDose = mock(ItemComposition.class);
		when(fourDose.getName()).thenReturn("Prayer potion(4)");
		when(twoDose.getName()).thenReturn("Prayer potion(2)");
		when(itemManager.canonicalize(100)).thenReturn(100);
		when(itemManager.canonicalize(101)).thenReturn(100);
		when(itemManager.getItemComposition(100)).thenReturn(fourDose);
		when(itemManager.getItemComposition(101)).thenReturn(twoDose);
		SupplyRecommendation prayer = new SupplyRecommendation(100, 100,
			"Prayer potion(4)", "Prayer restore", "test", SupplyStatus.PACKED,
			true, 8, 8, 0, "doses");
		GearRecommendations recommendations = ready(prayer);
		TaskConsumptionTracker tracker = new TaskConsumptionTracker();

		tracker.start(recommendations, new Item[]{new Item(100, 2)}, itemManager, 1_000);
		tracker.observe(new Item[]{new Item(101, 2)}, itemManager, 7);
		TaskCompletionSummary summary = tracker.finish(0, 62_000);

		assertNotNull(summary);
		assertEquals(10, summary.getKills());
		assertEquals(61, summary.getElapsedSeconds());
		assertEquals(Collections.singletonList("Prayer restore 4 doses"), summary.getConsumed());
		assertFalse(tracker.isActive());
	}

	@Test
	public void selectedBossPlanStillTracksUnderlyingAssignmentIdentityAndAmount()
	{
		TaskConsumptionTracker tracker = new TaskConsumptionTracker();
		GearRecommendations bossPlan = GearRecommendations.ready("Vorkath", 1, null,
			GearStrategy.builder().name("Boss").build(), Collections.emptyList(),
			Collections.emptyMap(), Collections.emptyList(), Collections.emptyList(),
			Collections.emptyList(), ReadinessReport.empty(), 1);

		tracker.start(bossPlan, "Blue dragons", 42, new Item[0],
			mock(ItemManager.class), 0);
		TaskCompletionSummary summary = tracker.finish(40, 10_000);

		assertNotNull(summary);
		assertEquals("Blue dragons", summary.getTaskName());
		assertEquals(2, summary.getKills());
	}

	@Test
	public void accumulatesFoodAcrossBankTripsOnlyWhenTaskCounterFalls()
	{
		ItemManager itemManager = simpleItemManager(200, "Shark");
		SupplyRecommendation food = supply(200, "Shark", "Food", "items");
		TaskConsumptionTracker tracker = new TaskConsumptionTracker();

		tracker.start(ready(food), "Abyssal demons", 10,
			new Item[]{new Item(200, 10)}, itemManager, 1_000);
		tracker.observe(new Item[]{new Item(200, 8)}, itemManager, 10);
		tracker.observe(new Item[]{new Item(200, 8)}, itemManager, 9);
		tracker.resume(ready(food), "Abyssal demons", 9,
			new Item[]{new Item(200, 10)}, itemManager, 5_000);
		tracker.observe(new Item[]{new Item(200, 7)}, itemManager, 8);
		TaskCompletionSummary summary = tracker.finish(8, 10_000);

		assertEquals(2, summary.getKills());
		assertEquals(Collections.singletonList("Food 5 items"), summary.getConsumed());
		assertEquals(9, summary.getElapsedSeconds());
	}

	@Test
	public void ignoresFoodUsedWithoutConfirmedTaskProgress()
	{
		ItemManager itemManager = simpleItemManager(200, "Shark");
		SupplyRecommendation food = supply(200, "Shark", "Food", "items");
		TaskConsumptionTracker tracker = new TaskConsumptionTracker();

		tracker.start(ready(food), "Abyssal demons", 10,
			new Item[]{new Item(200, 10)}, itemManager, 1_000);
		tracker.observe(new Item[]{new Item(200, 5)}, itemManager, 10);
		tracker.resume(ready(food), "Abyssal demons", 10,
			new Item[]{new Item(200, 10)}, itemManager, 5_000);
		TaskCompletionSummary summary = tracker.finish(10, 10_000);

		assertTrue(summary.getConsumed().isEmpty());
	}

	@Test
	public void finalTaskKillCommitsPendingFoodUse()
	{
		ItemManager itemManager = simpleItemManager(200, "Shark");
		SupplyRecommendation food = supply(200, "Shark", "Food", "items");
		TaskConsumptionTracker tracker = new TaskConsumptionTracker();

		tracker.start(ready(food), "Abyssal demons", 1,
			new Item[]{new Item(200, 10)}, itemManager, 1_000);
		tracker.observe(new Item[]{new Item(200, 8)}, itemManager, 1);
		TaskCompletionSummary summary = tracker.finish(0, 2_000);

		assertEquals(Collections.singletonList("Food 2 items"), summary.getConsumed());
	}

	private static ItemManager simpleItemManager(int itemId, String name)
	{
		ItemManager itemManager = mock(ItemManager.class);
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getName()).thenReturn(name);
		when(itemManager.canonicalize(itemId)).thenReturn(itemId);
		when(itemManager.getItemComposition(itemId)).thenReturn(composition);
		return itemManager;
	}

	private static SupplyRecommendation supply(
		int itemId, String name, String category, String unit)
	{
		return new SupplyRecommendation(itemId, itemId, name, category, "test",
			SupplyStatus.PACKED, true, 10, 10, 0, unit);
	}

	private static GearRecommendations ready(SupplyRecommendation supply)
	{
		return GearRecommendations.ready("Test task", 10, null,
			GearStrategy.builder().name("Test").build(), Collections.emptyList(),
			Collections.emptyMap(), Collections.emptyList(), Collections.emptyList(),
			Collections.singletonList(supply), ReadinessReport.empty(), 1);
	}
}

package com.freearcanes.slayergear;

import java.util.LinkedHashMap;
