		TravelItemAdvisor.TravelRule route = find(
			TravelItemAdvisor.recommend("God Wars Dungeon", null, config),
			"Trollheim teleport");

		assertArrayEquals(
			new String[]{"law rune", "trollheim teleport"},
			route.getPreferredNames());
